INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler Kaçar Gibidir', 'anneler-kacar-gibidir-turgut-uyar-mn8u7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'söyle ben saçlarımı kestirirsem ne olur

bir başkaldırma ancak saçlarından tutulur

herkes annesi sanır bir kısır yalnızlığı

oysa herkesin annesi aslında bir baruttur

eylülden ürken temmuz şafaktan korkan gece

dağları bölümleyen o babadan kaçan sudur

hatırla her gün bir çalar saatle oynadığını

çalar saatler bir çocuğun uyanılacak uykusudur

soğuk iklimler, kırımlar akar gider derisinden

ça
..........
..........', 'söyle ben saçlarımı kestirirsem ne olur bir başkaldırma ancak saçlarından tutulur herkes annesi sanır bir kısır yalnızlığı oysa herkesin ann...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 9, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Klasikleri","is_hero":true,"total_lines":12,"source_url":"https://www.antoloji.com/anneler-kacar-gibidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Yorumcuları’na', 'su-yorumculari-na-turgut-uyar-03lr9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1

ben ne güzel işerim güneşe karşı

arkamda medrese duvarı önümde çarşı

bir sürekli kaşınmadır yaşadığım

törelere ve alışkanlığa karşı

geldim gittim geldim 
..........
..........', '1 ben ne güzel işerim güneşe karşı arkamda medrese duvarı önümde çarşı bir sürekli kaşınmadır yaşadığım törelere ve alışkanlığa karşı geldim...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 9, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Klasikleri","is_hero":true,"total_lines":8,"source_url":"https://www.antoloji.com/su-yorumculari-na-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acının Tarihi', 'acinin-tarihi-turgut-uyar-c82d8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kalın ve karanlık bir çatı merdiveni gibi

giderilmez eksikliğini tanırım onun

suyun bardakta duruşu gibi

bir öfke usul usul büyürken kuytuda

yemyeşil bir çayır görünümündedir

haziran ortasında bir gümüş lüfer

büyülü bir fotoğraf bir gümüş çerçevede

ve evinde hemen hazır bir silah

böyle kargaşalı günler döneminde

beşer onar koparılan bir takvim sanki

bahara

bunlar güzel şeyler biliyorum

herkes de biliyor kuşkusuz

..........
..........', 'kalın ve karanlık bir çatı merdiveni gibi giderilmez eksikliğini tanırım onun suyun bardakta duruşu gibi bir öfke usul usul büyürken kuytuda...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 9, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Klasikleri","is_hero":true,"total_lines":15,"source_url":"https://www.antoloji.com/acinin-tarihi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Münacat', 'munacat-turgut-uyar-inchw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'birden hatırladık seninle buluşamadığımız günleri

gel ey büyük bakış yüce suskunluk gel artık beri

kentleri ve kasabaları ve köyleri çevirdik senin adına

kapıları tutmaktan artık herkesin nasır oldu elleri

olsun daha da tutarız sen varsan düşüncemizde ama gel

tutarız karaları ve denizleri ve yaşayan yürekleri

kendin karşı koydun yaptığın saraylara zindanlara tellere

yine kendin kullan artık kendi yaptığın tüfekleri

bozgun bir şu
..........
..........', 'birden hatırladık seninle buluşamadığımız günleri gel ey büyük bakış yüce suskunluk gel artık beri kentleri ve kasabaları ve köyleri çevirdi...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 9, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Klasikleri","is_hero":true,"total_lines":11,"source_url":"https://www.antoloji.com/munacat-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylenir Ve Yarım Kalır', 'soylenir-ve-yarim-kalir-turgut-uyar-gb87w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söylenir ve yarım kalır

bütün aşklar yeryüzünde

bir kaktüs bol sudan nasıl

nasıl çürürse, öyle

En sevdiğim temmuzdu aylardan

hazirana benzediği için biraz

biraz da kendiliğinden

belki de müşteriye iyi davranan

efendi bir bakkal kimliğinde

Nasıl mutlu oldum iki yaz

nasıl mutlu oldum kardeşler

Salkımsöğüt bir, ben iki

bir üçüncü var mıydı bilmiyorum', 'Söylenir ve yarım kalır bütün aşklar yeryüzünde bir kaktüs bol sudan nasıl nasıl çürürse, öyle En sevdiğim temmuzdu aylardan hazirana benzed...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 9, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Klasikleri","is_hero":true,"total_lines":13,"source_url":"https://www.antoloji.com/soylenir-ve-yarim-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Başlangıcında Düşünceler', 'bahar-baslangicinda-dusunceler-turgut-uyar-2tc53', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi Palandöken''de çoban Ahmet''in

Tabanlarının üç metre altında,

Sessiz bir bahar başlamaktadır.

Yol bulmuş da, kar suları toprağa

İnce bir sevda gibi işlemektedir.

Böcekler tohumlar kıvır kıvır

Akdeniz''de, meyve bahçelerinde

Çocuklar erikleri taşlamaktadır.

Benim de kötü geçmedi çocukluğum

Geçende oturdum da düşündüm.

Her gününde bir başka tad bulduğum,

İstanbul''un bir kenar mahallesinde,

Veya Eskişehir''de evimizdeyken.

Şöyle birkaç saat düşteydim sandım

Sanki rahat bir toprakmışım da, içime

Bir cemre düşmüş gibi ısındım.

Babam zabitti o zamanlar

Şa
..........
..........', 'Şimdi Palandöken''de çoban Ahmet''in Tabanlarının üç metre altında, Sessiz bir bahar başlamaktadır. Yol bulmuş da, kar suları toprağa İnce bir...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 9, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Klasikleri","is_hero":true,"total_lines":20,"source_url":"https://www.antoloji.com/bahar-baslangicinda-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemiş Bir Paket Cigaranın Son Umudu''na', 'beklemis-bir-paket-cigaranin-son-umudu-na-turgut-uyar-qa1q1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte suyumuzu kestiler ama masamda yine bir çiçek

bir çiçeğin akşamı elbet bir çiçeğe benzeyecek

nasıl güzel nasıl diri bir çiçek

dipdiri adamlardan biri bir çiçek

evet ben son ve kesin umuduyum bir paket cıgaranın

bir köhne câmekanda sararmış alıp içmemi bekleyecek

sonsuz bir camekânda

başlangıçsız bir çiçek

alırım seni tüttürürüm bir gün güzel tütün

söyle kim var bunu benden daha iyi bilecek

ey kalın duman gün senindir

kim var senden daha doğru tütecek

ben gelirim seni alırım büyük alanlara gideriz

s
..........
..........', 'İşte suyumuzu kestiler ama masamda yine bir çiçek bir çiçeğin akşamı elbet bir çiçeğe benzeyecek nasıl güzel nasıl diri bir çiçek dipdiri ad...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 9, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Klasikleri","is_hero":true,"total_lines":16,"source_url":"https://www.antoloji.com/beklemis-bir-paket-cigaranin-son-umudu-na-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
