INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-behcet-necatigil-2b24v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gün 

Enginlerden engin 

Yücelerden yüce 

Bir duygu sarar bizi 

Bu sınıfa girince. 

Yanda, bir uçtan bir uca. 

Mavi deniz 

Odanın içinde güneşleri bulunca. 

Isınırız. 

Enginlerin engini deniz olsa 

Deniz ufak! 

Yücelerin yücesi güneş olsa 

Güneş küçük! 

İlk günü gördük, nerden geldi: 

Duvardaydı 

Denizleri, güneşleri 

Küçülten büyüklük. 

Kürsünün üstünde bir resim: 

Gözleri denizlerden mavi 

Bakışları güneşlerden sıcak. 

Dört mevsim. 

Kürsünün üstünde: 

Atatürk''üm, arkasında al bayrak 


..........
..........', 'Her gün  Enginlerden engin  Yücelerden yüce  Bir duygu sarar bizi  Bu sınıfa girince.  Yanda, bir uçtan bir uca.  Mavi deniz  Odanın içinde ...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 9, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Klasikleri","is_hero":true,"total_lines":25,"source_url":"https://www.antoloji.com/resim-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilim', 'kilim-behcet-necatigil-jks7m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kilimde incir çekirdekleri –parlak, pahalı

Elmaslar yerine çekirdek– süs, avunma.

Hatta soluk, ucuz boncuklar olabilirdi,

–Cam boncuk, incir çekirdekleri – süs, avunma.

Gezdir parmaklarını: Pürtük! Çünkü üzüm çöpleri…

Aptallığımızdan kalma üzüm çöpleri, armut sapları.

Ama biz dokuduk bu kilimi, eh bir dereceye kadar! 

Değil ele güne çıkacak, değil asılacak duvarlarda.

Çiğnenir –çok çiğ çağ– ayaklar altında yabansı.

Sağlam olabilirdi, saplar aldattı bizi:

Üzüm çöpleri, armut sapları, çekirdek, çok çiğ

Önceden düşünemedik, çok çiğ çağ! 

Renkler, oldu bir kere, geçti, renkler…

Düşünmek gerekli başlarken, sen buna

Renk m
..........
..........', 'Kilimde incir çekirdekleri –parlak, pahalı Elmaslar yerine çekirdek– süs, avunma. Hatta soluk, ucuz boncuklar olabilirdi, –Cam boncuk, incir...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 9, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Klasikleri","is_hero":true,"total_lines":17,"source_url":"https://www.antoloji.com/kilim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Kuşun Öttüğü', 'deli-kusun-ottugu-fazil-husnu-daglarca-jr5fx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hey göklere duman durmuş dağlar hey

Değirmenin üstü her gün yel olmaz

Dinle ağa, dinle paşa, dinle bey

Sen söylersin o susar mı bell"olmaz

Kızılırmak akar suyun içerler

Aç karnına yurttan yurda göçerler

Tarifeylen Köprüsünü geçerler

Çamın başı yine kar mı bell"olmaz

Olmaz artık olanlar böyle olsun

Yeni çağda mızrak çuvala girsin

Vergi dersin, ümük dersin, can dersin

Verdiler mi aldılar mı bell"olmaz', 'Hey göklere duman durmuş dağlar hey Değirmenin üstü her gün yel olmaz Dinle ağa, dinle paşa, dinle bey Sen söylersin o susar mı bell"olmaz K...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":12,"source_url":"https://www.antoloji.com/deli-kusun-ottugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Dil Kurumu Koçaklaması', 'turk-dil-kurumu-kocaklamasi-fazil-husnu-daglarca-f80gj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÇAĞRI

Ata''dan oğula dek

Geceleyin gürültüler duruca

Dört yana dağılır kocaman bir çağrı

Türk Dil Kurumu''nun görkemli yapısından

Divanü Lügat-it Türk''te.

Türerken yeni sözcüklerimiz

Bu senin yazmandır söylemendir

Yönündür

Bilincindir

Uygarlığındır

Özgürlüğündür

Bu senin yarınındır ey Türk genci



ORTAASYALILARIMIZ – 1

Gün ışıdı mı çıkar

Türkçe sözcükler dışarı

Türk Dil Kurumu''ndan

Varırlar yaban adları almış yerlere

Dururlar

Gözlerimiz görene dek



ORTAASYALILARIMIZ – 2

İşte giderler

Koridar’a geçenek sözcüğü

Viraj’a dönemeç 

İstasyon’a durak

İmalathane’ye işyeri 

Atelye’ye işlik 

Plaj’a kumsal 

Arşiv’e belgelik

Garaj’a taşıtlık

Gardrop’a giysilik 

Mayo’ya denizlik

Rıhtım’a gemilik

Balkon’a çıkıt

Mezbaha’ya kanara 

Mezarlığa gömütlük

Türkçenindir bu ülke 

Çek git derler 

Kulaklarımız işitene dek



SON GÜCÜMÜZ

Buraya dek dedi dağ taş

Çatladı sallandı koptu düştü

İçindeki yabancı sözcükler

Ulu savunmasında Türkçemizin

Duymuştu yediden yetmişe tek tek

Bütün Türkler

Başkasının sözcükleriyle

Artık soluk alamıyacaklarını

Dirilir unutturulmuş söz

Dirilir bilinçaltındaki direnç

Bağımsızlık savaşlarında dirilir

Ulusların yaşama eylemleri

Anımsıyor musunuz Sakarya Savaşı''nın en

karanlık yerinde

Birliklerimize katılan son ordu

Dalkılıç dalyürek dalağız

Anadilimizdi bizim



DEVRİMİ BÖYLE ANLAMAK

Türk Dil Kurumu''nu kurarken

Mustafa Kemal''in

Tek mutsuzluğu vardı

Türkçeyi sevdiğim

Daha Türkçe söyleyememek

Kimilerinin

Şimdi

Tek mutluluğu var

Türkçe''yi sevdiklerini

Daha Osmanlıca söylemek

İLKOKULLARDA

Sözcükleri bu koçaklamanın

O kuşlardır ki

Uçarlar doğarken güneş

Bütün ilkokullarımıza konarlar kent kent

Nerden mi biliyorum

İşittiklerimden:

Duymuyor musunuz çınlayan sesleri

“Ne bahtiyar Türklüğünü ifâde eden”

Demiyorlar da öğrencilerimiz

Tam Atatürk doğrultusunda

“Ne mutlu Türküm diyene” diyorlar

DİL’LE VAROLMAK

İstiklâl derken

Yok olur bağımsızlığımız bizim

Yok olur

Hürriyet derken özgürlüğümüz

UYUMAK

Dilin gözü

Uyanık değilse

Uyanamaz

Çağlarına, okumuşlarımız yazmışlarımız

ÜSKÜDAR

Atı alan

Üsküdar’ı geçmiş

Kimileri

Üsküdar’dan da geridedir

Attan da

SONSUZ

Dil yurttaşlığı

Yurttaşlıktan büyüktür

Sürüp gider o

Kişi öldükten sonra bile

DOĞRU YOL

Arı dil

Anlama eşitliği demektir

Anlama eşitliği

Yurttaşlık

AÇ ZENGİNLİĞİMİZ

Yoktur

Türkçesi olmayan sözcük

Ya unutulmuştur o

Ya anımsanmamıştır

DOĞRU ANLAMANIN NEDENİ

Soyları vardır

Sözcüklerin

Soy birliği olmadı mı

Anlam birliği olmaz anlatımda

İKİ DOĞRU

Ana 

Çocuğu somutlar

Anadil

Çocuğun kişiliğini

KAYALARA OYDUĞUM YAZI

Suçludur

Çağın sözcüklerini aramak yerine

Bizi

Osmanlıca’yla bir daha uğraştıran

İNANÇ

Ekmek gibi yeseler de

Su gibi içseler de ülkümüzü bizim

Onları gerçeğe eriştirir bir gün

Bu ekmek bu su

TÜRKÇE KATINDA YAŞAMAK

Seslenir seni bana ''sonsuz'' 

Der ki çoğal, 

Der ki uzun mutluluğuna 

Usun iyiliğin doğruluğun, 

Bir bilinmeyenden bir bilinene dek 

Türkçe, varolduğumuz.

Türkçe, nice desem seni, 

Onca güzelim. 

Görünmek derinleşmek, 

Dolmak; 

Seni düşünürüm düşünürüm, yarı karanlıklarda, dal, 

Anlarım onca. 

Bir bölü beş, bir bölü dokuz, 

Bir bölü bin üç:

Ayrılık anlamların öylesine azar azar dağılır, 

Ta doğudaki balık, 

Duyar kokusunu 

Ta batıdaki yoncanın. 

Seslenir seni bana yakın uzak, 

Yeryüzü mavisinden gökyüzü yeşiline, 

Tutsak uluslar var ya geceler boyu 

Onlar için

Yitik özgürlükler için, 

Türkçe, haykırmak.

O süre yaradılış dar iken 

Düz iken, yassı iken, 

Daha''lar

Daha''lar

Daha''lar daha''lara karışmış, 

Sınırsızlığın getirmiş yarınları. 

Konuşamaz iken, o yusyuvarlakta, 

Diyemez iken, 

Artısı eksisi almış götürmüş 

Toprağın bitkilerden arta kalan sağlığını

Sıcak uzun,

Bir kişiler geleceğine.

Seslenir seni bana bir duru su

İçinde masallar uygarlıklar saklayan,

Eski ozanlar kazımış ilk yazıları ilk anıtlara, 

yankılanır 

Alandan alana, uçsuz bucaksız, 

Evrenden akınlarının uğultusu. 

Ama bağışla beni, unutmuşum, 

Yıldızını güneşini ayını, utanmadan.

Öyle köksüz günlerim gelmiş bozkır çadırlarından çırılçıplak, 

Unutmuşum ana demesini bile, 

Öykünmüşüm türküsünü ellerin, 

Ağzıma bir kara düşmüş bağışla beni. 

İşte andiçiyorum,

Bütün ölüler adına, 

Bütün gençler, bütün doğacak çocuklar adına, 

Varacağım deyişine gündüz gündüz, 

Varacağım tanrıya dek, 

Soluğumda soluğun.

Seslenir seni bana ''ova''m, ''dağ''ım, 

Nere gitsem bulur beni arınmış. 

Bir çağ ki akar ötelere, 

Bir ak.. ki yüce atalar, bir al.. ki ulu oğullar, 

Türkçem, benim ses bayrağım.', 'ÇAĞRI Ata''dan oğula dek Geceleyin gürültüler duruca Dört yana dağılır kocaman bir çağrı Türk Dil Kurumu''nun görkemli yapısından Divanü Lügat...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":191,"source_url":"https://www.antoloji.com/turk-dil-kurumu-kocaklamasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahraman', 'kahraman-fazil-husnu-daglarca-16ale', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gölgen bir nur işledi güneşe vardığı gün; 

Seni gördük sesimiz Hak''ka yalvardığı gün,

Seni gördük bir mazi dağları sardı ses ses,

Bir Akdeniz dalgası buldu içinde herkes...

Sana çıkar bu yurdun ararsak son yolu da,

Kutlu bir Tanrı oldun güzel Anadolu''da.

O kadar eskisin ki şimdi ruhumuzda sen,

Bulursun bu sevgide asırları istersen.

Ararsan bakışında uzun ovalar erir,

Dinlersen gönül denen yüce dağlar ses verir.

Bir dünya, bir millete düşman olduğu zaman

Sana büyük hızını verdi nabzındaki kan..

Dört sınırın ucunu getirdin bir araya,

Dört bucak sevgisini topladın Ankara''ya.

Sesin, bir tılsım gibi, yurdu dolaştı yer yer

Ve senden öyle keskin hız aldı ki gönüller,

Yüzyılda giden vatan bir anda geri geldi...

Sonra sanki ruhunda kartal sesleri geldi; 

Sanki yeni bir ışık süzüldü gözlerinden

Ve bir fert, tek başına, bir millet yarattın sen.

Bastığın yer tarihten yer alırmış, yok, değil:

Bir gününe bir tarih bağışlasak çok değil! 

Çok değil, kanımızın rengini süze süze,

İsmini döğmelerle işlesek göğsümüze..

Çok değil göğsümüzün içine çizsek seni.

İsterse bundan sonra ufuk yansın, gök yansın; 

Çünkü sen bu milletin umduğu kahramansın...

Gölgen bir nur işledi güneşe vardığı gün; 

Seni gördük sesimiz Hak''ka yalvardığı gün.', 'Gölgen bir nur işledi güneşe vardığı gün;  Seni gördük sesimiz Hak''ka yalvardığı gün, Seni gördük bir mazi dağları sardı ses ses, Bir Akdeni...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":29,"source_url":"https://www.antoloji.com/kahraman-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-fazil-husnu-daglarca-nck1f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'A''dan başlar aydınlık,

Bir taş koyar bütün yapılarda temele öğretmen.

Soluğudur düşüncenin buğdaydan yalaza dek

Yeryüzünde ne varsa ondan gelmedir,

Yeryüzü ile el ele öğretmen

Göz gözdür o, uzakları görürüz

Ağızdır o, türkü söyleriz haykırırız günlerden.

Ulaşırız erdem üstüne, gelecekler üstüne biz hep

Çizer büyük değirmisini

Uç olur da gergele öğretmen.

Hey hey, burası bir dağ köyü, kurda kuşa

Bırakılmış göğün kıyısına bırakılmış

83 toprak ev, 83 acı duman,

Çoluğuyla, çocuğuyla 415 karanlık

Kurtulacağız, el ayak kurtulacağız,

Bir okul yapıla, bir gele öğretmen.

Bir ışık, bir ışık daha,

Gecelerin içindeki ejderlerle dövüşür

Nice istemeseler de, nice önleseler de,

Uyandırır toplumunu

İyiye, doğruya, güzele öğretmen.', 'A''dan başlar aydınlık, Bir taş koyar bütün yapılarda temele öğretmen. Soluğudur düşüncenin buğdaydan yalaza dek Yeryüzünde ne varsa ondan ge...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":21,"source_url":"https://www.antoloji.com/ogretmen-191-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Yapraklı Çiçek', 'dort-yaprakli-cicek-fazil-husnu-daglarca-qkte0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıkamaz çocukluğundan dışarı

Kimse.

Oynamamız bundandır.

Kara toprakla binlerce yıl.

Çıkamaz çocukluğundan dışarı

Kimse.

Bundandır sevmemiz

kiraz ağaçlarını.

Çıkamaz çocukluğundan dışarı

Kimse.

Kardeşliğimiz bundandır

Mavi sularla binlerce yıl.

Çıkamaz çocukluğundan dışarı

Kimse

Bundandır inanmamamız

Kocaman bombalara.', 'Çıkamaz çocukluğundan dışarı Kimse. Oynamamız bundandır. Kara toprakla binlerce yıl. Çıkamaz çocukluğundan dışarı Kimse. Bundandır sevmemiz ...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":16,"source_url":"https://www.antoloji.com/dort-yaprakli-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul Çocukların El İşi Vazifesi', 'mechul-cocuklarin-el-i-si-vazifesi-fazil-husnu-daglarca-x250n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oturmuştuk büyük masanın etrafına,

Babam gazete okuyordu, biz ders çalışıyorduk.

Hesap vazifesini aceleyle yapıyordum,

Vardı benim içimde başka yolculuk.

Nihayet sıra geldi babamdan çekinerek,

Çıkardım el işi defterimi çantamdan.

Mektepte başladığım bir iş vardı nur gibi

Ki nur kesiliyordum aklıma geldiği an.

Masallar ve rüyaler gibi kalpler kesmiştim,

El işi kâğıtlarının birçok rengiyle.

Renklerin arasındaki sevgiyi anlayarak

Yapacaktım onlardan bir aile.

Birbirlerinden sonra çok güzel oldular,

Ellerim yanıyordu değdikçe onlara.

Kalpler, parlak, güzel ve bin hülyaya doğru,

Kalpler, yaşar gibi, rabbim ne manzara.

Ve nihayet dirseğimle dürttüm,

Çağırdım kardeşimi saadetime kadar.

O baktı ve hepsi baktı hayretle,

Kitapları terkedip hülyama karıştılar.

Artık el işi kâğıtları fazla mı parlıyordu,

Kalplerin zarif şekli daha mı incelmişti ne.

Annem bile çevirmişti başını,

Ilık odamızın bu tuhaf sessizliğine.

Ve babam birdenbire hissetti

Gözlüğünün üstünden süzdü halimizi.

Kızıyor gibiydi kitaplar bırakılmış,

Bana işaret verdi ablamın dizi.

Mavi damarları çıkmış kocaman elini,

Uzattı babam bize doğru gülerek.

Aldı defterimi ve seyretti tatlıca,

Başını sallarken dedi: güzel gerçek.

Fakat düşmüş bir tanesi, diye devam etti,

O zaman biz güldük yaramaz ve çılgın.

Beyaz kalbi görmemişti ne tuhaf,

Hayretimiz ve neşemiz üstündeydi hayatın.

Ve birgün bana baban öldü dediler,

Hissederken renkleriyle nasibim olan yurdu.

O el işini hatırladım, ağlayarak,

Acaba onlar da mı beyaz kalbi görmüyordu!', 'Oturmuştuk büyük masanın etrafına, Babam gazete okuyordu, biz ders çalışıyorduk. Hesap vazifesini aceleyle yapıyordum, Vardı benim içimde ba...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":40,"source_url":"https://www.antoloji.com/mechul-cocuklarin-el-isi-vazifesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Misafir', 'buyuk-misafir-fazil-husnu-daglarca-3n6x8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevinç incilemiş gözleri yaşlar yerine,

İzi üstünde gül açmış kapanan her yaranın.

Bir bahar yağmuru halinde derinden derine

Çağlıyor her yanı alkışla yeşil Marmara''nın.

Bu misafirdir, inan memleketin neyse varı,

Böyle bir yüz mü görür bir daha fâni ömrün? 

Gelin ay Bahr-i Muhit''in köpüren dalgaları,

Kırk asırlık yolu bir hızda alan Türk''ü görün', 'Bir sevinç incilemiş gözleri yaşlar yerine, İzi üstünde gül açmış kapanan her yaranın. Bir bahar yağmuru halinde derinden derine Çağlıyor he...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":8,"source_url":"https://www.antoloji.com/buyuk-misafir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mushaf', 'mushaf-fazil-husnu-daglarca-52x5c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '… ve nelerden sonra ben hatırlıyorum,

Bazı geceler, yani her gece.

Babamın ve başka sevgililerin Arapçasını

Tesellisiz şeyler düşündükçe.', '… ve nelerden sonra ben hatırlıyorum, Bazı geceler, yani her gece. Babamın ve başka sevgililerin Arapçasını Tesellisiz şeyler düşündükçe....', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":4,"source_url":"https://www.antoloji.com/mushaf-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Ve Karanlık', 'siyah-ve-karanlik-fazil-husnu-daglarca-dc0xy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kur’an okurdu babam bazen

Galiba Kadir gecelerinde

Onun inanmış sesiyle biz çocuklar

Daha küçülürdük odanın en uzak bir yerinde.

Müteessir olurduk kışı gören kırlangıçlar gibi,

Garip sadalarda hiçbir şey anlamadan.

Henüz mektebe giden ablam, bilgiç bilgiç:

‘Arapça’ derdi, nefesiyle o zaman.

Arapça. Uzak karanlıklarda,

Siyah ve lâmba sönmüş gibi… uzar.

Ve çocuk kalplerimizi mâtemiyle kaplardı

Meçhul ölülere âit mezarlar.

Arapça’dan nefret ederdik, lâkin,

Okşardı babamın okuduğu şey, muhayyilemizi.

Korkudan ve hayretten bir yeni dünya içinde

Muhakkak ki iman zaptederdi bizi.

Bir sesten sonra muhakkak bir başka ses gelirdi,

Ama nasıl başka, anlatılmaz.

Babamın sonsuz âhengi arasında

Olurdu yaşamalar daha az.

Ve olurdu vücûdumuzdaki tarif edilmez çocukluk,

Nedense, daha uzun.

Uyanırdı karanlık hücrelerde,

Bütün yâdigârlığı, ruhumuzun.

Ve babamın nefesleri yavaşlardı, hep aynı seslerle,

Tevekkül ve akıl dolu gelirdi bize, her taraf.

Babamın elleri büyürdü ve büyürdü babamın ellerinde', 'Kur’an okurdu babam bazen Galiba Kadir gecelerinde Onun inanmış sesiyle biz çocuklar Daha küçülürdük odanın en uzak bir yerinde. Müteessir o...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":27,"source_url":"https://www.antoloji.com/siyah-ve-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitaplar Arasında Çiçekler', 'kitaplar-arasinda-cicekler-fazil-husnu-daglarca-1bu00', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bıraktın bir hatıralar yığınında beni de yavrum; 

Ki sevgim verdi sana bir koku gibi bütün dünyasını.

Ve ben bu sabah vaktinde iyice hissediyorum,

Bir kitap arasına bırakılmış çiçeklerin yasını.', 'Bıraktın bir hatıralar yığınında beni de yavrum;  Ki sevgim verdi sana bir koku gibi bütün dünyasını. Ve ben bu sabah vaktinde iyice hissedi...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":4,"source_url":"https://www.antoloji.com/kitaplar-arasinda-cicekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kocaman Bolu', 'kocaman-bolu-fazil-husnu-daglarca-97q2p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuşlarda ses yellerde ses, dağda ses,

Bir türküdür aramızda akan şey.

Toprakların birliğini demez mi

Ayvaların sarılığı kardeşim? 

Burda duyduğum duyduğum

Nane kokusu kokusu.

Hadi beni sevmediniz

Getirdiğim maviliği alsanız ellerimden.', 'Kuşlarda ses yellerde ses, dağda ses, Bir türküdür aramızda akan şey. Toprakların birliğini demez mi Ayvaların sarılığı kardeşim?  Burda duy...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":8,"source_url":"https://www.antoloji.com/kocaman-bolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Verilen', 'geri-verilen-fazil-husnu-daglarca-10mm7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Peki alınız sizin 

Daha istemiyorum 

Bu el bu ayak 

Bu duyu bu düşünce 

Sizin 

Daha istemiyorum

Dallarda göklerde sularda 

Açılarım bir denklemle uykusuz 

Belki anlarlar beni 

Sevindirirler umdururlar ama 

Sizin 

Daha istemiyorum

Ta çocukluğumdan beri 

Yanım sıra yürüyen 

Sevince acıkınca 

Konuşunca yazınca duyduğum şey 

Sizin 

Daha istemiyorum

Gece koyu karanlıklar büyür 

Alır tasalarımı yollarda 

Alır güzelliğimi dağlardan 

Peki sizin bu doldurduğum boşluk 

Sizin 

daha istemiyorum

Hepsi taş toprak orman deniz 

Işıksızlığını yaşadığım varlık 

Yokluğunda ağrıdığım ölüler 

Hepsi hepsi 

Sizin 

Daha istemiyorum', 'Peki alınız sizin  Daha istemiyorum  Bu el bu ayak  Bu duyu bu düşünce  Sizin  Daha istemiyorum Dallarda göklerde sularda  Açılarım bir denk...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":30,"source_url":"https://www.antoloji.com/geri-verilen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmediğim Ölüler İçinde', 'bilmedigim-oluler-i-cinde-fazil-husnu-daglarca-rd0vx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmediğim ölüler içinde yası

Mezartaşı olmayanın mezartaşıyım', 'Bilmediğim ölüler içinde yası Mezartaşı olmayanın mezartaşıyım...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":2,"source_url":"https://www.antoloji.com/bilmedigim-oluler-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adına Kızan', 'adina-kizan-fazil-husnu-daglarca-0bd7r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dedi ki kuşkonmaz

Düşte kımıldar gibi

Çok kızıyorum

Adımı böyle koyanlara ben

Ya kuşlar duyarsa bunu

Ya

Bile bile konmazlarsa bana

- Bilmiyorum

Ellerine ne geçecek

Ne kazanacaklar

Adımı kuşkonmaz koyanlar', 'Dedi ki kuşkonmaz Düşte kımıldar gibi Çok kızıyorum Adımı böyle koyanlara ben Ya kuşlar duyarsa bunu Ya Bile bile konmazlarsa bana - Bilmiyo...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":11,"source_url":"https://www.antoloji.com/adina-kizan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyanın Bütün Çocuklarına Karşı Yazılmıştır', 'dunyanin-butun-cocuklarina-karsi-yazilmistir-fazil-husnu-daglarca-z7jrd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hepiniz elele bir halka yapsanız

Rüyadan ve şarkıdan bir halka

Ve almasanız kimseyi ortanıza

Benden başka

Masallar gibi silinse etrafımız

Şehzadeniz olsam sizin

Biz mektebi ve dersi ebediyen terkettik

Ne olurmuş anneler vermezse izin

Seyretsem yüzünüzü birer birer

Ve birer birer seyretseniz beni

Garip saadetler duysak

Bayramlıklar kadar yeni

Nasip değil sadece gökler midir

Üstümüzden ninniler gibi geçen

Yavaşça görünürken karşı dağlar

Oyuncaklar mı hatırlarız devlerden

Gülsek küçük fidanlara sebepsiz

Mesela uçan kuşlar bir tuhaf gelse bize

Ve gölgesinde altın karanlıkların

Deliler gibi âşık olsak kendimize

Hani geçen sene kopan uçurtmamız

Kim bilir şimdi nereye gitti? 

Uykular ve güller arkasından

Oyunlar ki Allah’ın selâmeti

Siz dünyanın bütün çocukları geliniz

Rüyadan ve şarkıdan bir halka

Ne olur almayınız kimseyi

Ortanıza benden başka', 'Hepiniz elele bir halka yapsanız Rüyadan ve şarkıdan bir halka Ve almasanız kimseyi ortanıza Benden başka Masallar gibi silinse etrafımız Şe...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":28,"source_url":"https://www.antoloji.com/dunyanin-butun-cocuklarina-karsi-yazilmistir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Ağarırken', 'gun-agarirken-fazil-husnu-daglarca-n2kcb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle seviştiler ki

Kadın erkekte kaldı 

Erkek 

Kadında', 'Öyle seviştiler ki Kadın erkekte kaldı  Erkek  Kadında...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":4,"source_url":"https://www.antoloji.com/gun-agarirken-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Öğretmen', 'gunes-ogretmen-fazil-husnu-daglarca-xy5je', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş öğretmen

Sevdirir kendisini çok

Ona döner bitkilerin hepsi

Yoksa o

Onun aydınlığına döner hep

Olduğu olmadığı başka

Yaksa tam tepemizdeyken

Yandırsa da bizi

Kavursa da yalaz yalaz

Onun sıcaklığı başka

Bütün günler sürer

Öğrettikleri

Geceleyin bile

Karanlıkta dolaşır sözleri onun

Aydeden yıldızlardan başka', 'Güneş öğretmen Sevdirir kendisini çok Ona döner bitkilerin hepsi Yoksa o Onun aydınlığına döner hep Olduğu olmadığı başka Yaksa tam tepemizd...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":15,"source_url":"https://www.antoloji.com/gunes-ogretmen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurdu Severken Duymak', 'yurdu-severken-duymak-fazil-husnu-daglarca-1svli', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aç idi at

Aç idi er.

Aç idi at

Aç idi onbaşı

Aç idi çavuş.

Aç idi at

Aç idi

Üstçavuş

Başçavuş

Gedikli Efendi.

Aç idi at

Aç idi asteğmen

Üsteğmen

Aç idi at

Aç idi yüzbaşı

Aç idi önyüzbaşı

Aç idi eskil yüzbaşı

Binbaşı

Yarbay

Albay.

Aç idi at

Aç ta daha yukarısı

Ta daha.

Aydın''a yakın

Bir tepeye vardık ki

Arpa buğday

Kaçan sömürgenin bıraktığı

Yakamadan bıraktığı

On araba dolusu

Arpa buğday.

Erler yemeden geçti gitti

Albaylar paşalar yemeden geçti gitti.

At yemeden geçti gitti.

İzmir''e.', 'Aç idi at Aç idi er. Aç idi at Aç idi onbaşı Aç idi çavuş. Aç idi at Aç idi Üstçavuş Başçavuş Gedikli Efendi. Aç idi at Aç idi asteğmen Üste...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 9, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Klasikleri","is_hero":true,"total_lines":34,"source_url":"https://www.antoloji.com/yurdu-severken-duymak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz', 'beyaz-ziya-osman-saba-tj5i2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bademin altına, yorgun, oturmak biraz,

Ayrı ayrı seyretmek çiçek açmış her dalı.

Artık bütün renklerden, artık uzaklaşmalı:

Beyaz işte, aylardır gözümde tüten beyaz.

Kış bitti... Uzaklarda ilk ümitler gibi yaz,

Duyuyorum bu sabah, kış içimden çıkalı,

İçimin dört duvarı bembeyaz badanalı,

Ah, sade nefes almak, göğsüme dolan bu haz...

Bir kuş ötecek şimdi... Havada bir durgunluk,

Mermeriyle konuşan açık kalmış bir musluk,

Beyaz çiçeklerini tektük düşüren kiraz.

Bahar pınarlarından içime damlayan su,

Bembeyaz çiçeklerin ıslak, temiz kokusu,

Kış bitti... Uzaklarda ilk ümitler gibi yaz..', 'Bir bademin altına, yorgun, oturmak biraz, Ayrı ayrı seyretmek çiçek açmış her dalı. Artık bütün renklerden, artık uzaklaşmalı: Beyaz işte, ...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 9, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Klasikleri","is_hero":true,"total_lines":14,"source_url":"https://www.antoloji.com/beyaz-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''nsuz', 'o-nsuz-ziya-osman-saba-utx0l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah işte duyuyorum mesut günler içinden, 

Sana "sevimli yüzün asla solmasın" diyen, 

Bütün adınla dolu o coşkun şarkıları...

- Sen öldüğün için mi şimdi bayraklar yarı? 

Görüyorum ilk defa seni gördüğüm günü; 

Altından, alkışlarla geçiyorsun bir takın.

O gün bana gelmiştin babamdan daha yakın

Meğer duyacakmışım bir sabah öldüğünü...

Meğer görecekmişiz bir sabah gidişini,

İstanbul''un önünden son defa geçişini...

Bizler seninle nasıl, ne kadar beraberdik,

Bizler ki az sıkılsak "O başımızda" derdik; 

Nasıl yok bileceğiz o güzel güneş yüzü? 

Ana, baba değil bu, bizler Ata öksüzü

Tatmadık, bilmiyoruz bu bambaşka yarayı, 

Öğret bize yarabbim ah O''nsuz yaşamayı!', 'Ah işte duyuyorum mesut günler içinden,  Sana "sevimli yüzün asla solmasın" diyen,  Bütün adınla dolu o coşkun şarkıları... - Sen öldüğün iç...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 9, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Klasikleri","is_hero":true,"total_lines":16,"source_url":"https://www.antoloji.com/onsuz-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nişanlılık', 'nisanlilik-ziya-osman-saba-9m56m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nişanlılık

Hangi birini anayım,

Buluştuğumuz kumluk, uzak iskele.

Her yerde bir başkalık.

İlk defa gelişimiz el ele.

Sonra bir gün, kalabalık Beyoğlu,

Girdiğimiz dükkânlar, güler yüzlü satıcı.

İkimizi yanyana oturtup

Resmimizi çeken fotoğrafçı.

Rüzgâr dinmiş, ağaçlar dinler gibi.

Gün batarken o sakin sonbaharda; 

Akşamları dolaşmamız

Kolkola Mühürdar''da.

Bir adam sokak fenerlerini yakar,

İncecik vücudun vücuduma dayanırdı.

Her yolcu halden anlar

Bizi uzaktan tanırdı.

Duyageldiği parmaklarımın, o yüzükler...

Birinde benim adım, öbüründe senin adın.

Altın ışıklarıyla sanki,

Yepyeni, tertemiz bir hayatın.

Ne kadar ümitli, ne iyiydik! 

Önümüze düşmüş Bahtiyarlık,

İyi komşularla dolu mahallelerde,

Kiralık bir kat aradık.

Bir an gülümseyen talih, değişen kader

Ömrümde bir tek o sonbahar.

Ömrüm oldukça anacağım,

Bir rüya görür gibi geçtiğimiz sokaklar.', 'Nişanlılık Hangi birini anayım, Buluştuğumuz kumluk, uzak iskele. Her yerde bir başkalık. İlk defa gelişimiz el ele. Sonra bir gün, kalabalı...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 9, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Klasikleri","is_hero":true,"total_lines":29,"source_url":"https://www.antoloji.com/nisanlilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-ziya-osman-saba-lvz47', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz o kadar ağladık ki beraber, 

Gözyaşları doldurdu avucumu şimdilik. 

Şimdilik uzun uzun, bambaşka bir sessizlik 

Yavaşça alçalarak, yavaşça bizi dinler. 

Etrafta kalan sesler kesildi birer birer. 

Hatırlamaz olmuşum, her şey uzakta, silik. 

Yalnız senin vücudun... Ah içte bir içimlik 

Bir su gibi ellerin avucumda serinler. 

Vücudunun gölgesi bak yerde gölgemle bir, 

Yeni bir nefes gibi sessizlik göğsümdedir. 

Sessizlik içerime doluyor yudum yudum. 

Dolu bir yelken gibi göğsümde genişleyiş, 

Ve öyle için için, ve öyle geniş geniş. 

Ben hiç bir şey duymadan, ben yalnız seviyorum.', 'Biz o kadar ağladık ki beraber,  Gözyaşları doldurdu avucumu şimdilik.  Şimdilik uzun uzun, bambaşka bir sessizlik  Yavaşça alçalarak, yavaş...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 9, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Klasikleri","is_hero":true,"total_lines":14,"source_url":"https://www.antoloji.com/sessizlik-308-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Kimi Gördüler', 'gozlerim-kimi-gorduler-asaf-halet-celebi-qu8cf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Odalarda oturdum

Odaları kapladım

Sokaklara 
..........
..........', 'Odalarda oturdum Odaları kapladım Sokaklara  .......... .............', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 9, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Klasikleri","is_hero":true,"total_lines":5,"source_url":"https://www.antoloji.com/gozlerim-kimi-gorduler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hırsız', 'hirsiz-asaf-halet-celebi-g59u4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'pencereden giren mehtap

bu evde hırsız var

mehtapta

pencerede oturmuş

beni görüyorum

kapıyı çalsam

içerden ben çıkacağım

içerden çıkacak beni

ne kadar görmek istiyorum

penceredeki beni uyandırmalıyım

içerde hırsız var

içerdeki hırsızın

ben olacağımdan korkuyorum', 'pencereden giren mehtap bu evde hırsız var mehtapta pencerede oturmuş beni görüyorum kapıyı çalsam içerden ben çıkacağım içerden çıkacak ben...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 9, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Klasikleri","is_hero":true,"total_lines":13,"source_url":"https://www.antoloji.com/hirsiz-179-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misafir', 'misafir-asaf-halet-celebi-wwgx0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana bakarak

bütün yüzleri unutmak

kendimden

ve arap saçı olmuş

bir sürü

hi
..........
..........', 'sana bakarak bütün yüzleri unutmak kendimden ve arap saçı olmuş bir sürü hi .......... .............', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 9, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Klasikleri","is_hero":true,"total_lines":8,"source_url":"https://www.antoloji.com/misafir-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''umun Dili', 'i-stanbul-umun-dili-asaf-halet-celebi-m5emz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Annemin dili,

Babamın dili,

İstanbul''umun dili,

İstanbullumun dili.

İstanbul''umun efendisi,

Hanımefendisi.

Sokaklarımın bekçisi,

Yoğurtçusu, balıkçısı.

Can dilimi konuşanım,

Canım benim.

Ninnilerimi bu dil söyledi,

Masallarımı bu dil.

Bu dille duydum türkülerimi,

Bu dille okudum şairlerimi.

"Zalim beni söyletme derunumda neler var."', 'Annemin dili, Babamın dili, İstanbul''umun dili, İstanbullumun dili. İstanbul''umun efendisi, Hanımefendisi. Sokaklarımın bekçisi, Yoğurtçusu,...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 9, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Klasikleri","is_hero":true,"total_lines":15,"source_url":"https://www.antoloji.com/istanbul-umun-dili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimden', 'i-cimden-asaf-halet-celebi-k6c5a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dünyalar kuruldu

dünyalarda şehirler kuruldu 

ve birden 

kendimi bir şehirde buldum 

sokaklarda yürüyen 

yaşayan ve ölen insanlardan

kendimi bir şehirde buldum. 

karanlık gecelerde yürüdüm 

yarı aydınlık yerlerde oturdum 

adımı çağıran dost yüzler buldum 

dost dost diye haykırmak istedim 

içimden sevindim

düşünmedim ne başını 

ne sonunu 

düşünmedim ne kendimi 

ne de senin kim olduğunu 

yalnız 

senin için çok güzel rüyalar gördüm 

uyandım 

karşımda seni buldum 

dosttan daha dost 

güzelden daha başka

içimden sevindim 

içimden sevdim 

içimden', 'dünyalar kuruldu dünyalarda şehirler kuruldu  ve birden  kendimi bir şehirde buldum  sokaklarda yürüyen  yaşayan ve ölen insanlardan kendimi...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 9, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Klasikleri","is_hero":true,"total_lines":25,"source_url":"https://www.antoloji.com/icimden-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalar', 'ruyalar-asaf-halet-celebi-8zvm2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gün

karışık rüyalar görürüm,

sincâbi uykularda

hayaller belirir,

kaybolur.

Aynalar görürüm,

aynalarda rüyalar, 

bütün bahçeleri

kuşlarıyla

silinir.

Yüzler görünür,

yüzlerde gözler

yanıp söner,

hepsi bana bakar,

bir şeyler konuşur.

Uyanıklığımı ayıramıyorum

uykulardan.

karışık rüyalar içindeyim

ömrümün uykusunda.

Aynalardan beni çağıran kız

bir daha göründü,

işaret ediyor,

bitir rüyalarını da gel

diyor.

En son gördüğün yüz

benim olsun,

en son benim uykumda uyu.

Rüyaların sonu geliyor galiba,

uyanılmaz uykulara dalmak istiyorum...', 'Her gün karışık rüyalar görürüm, sincâbi uykularda hayaller belirir, kaybolur. Aynalar görürüm, aynalarda rüyalar,  bütün bahçeleri kuşlarıy...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 9, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Klasikleri","is_hero":true,"total_lines":29,"source_url":"https://www.antoloji.com/ruyalar-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pencereler Ve Kapılar', 'pencereler-ve-kapilar-asaf-halet-celebi-zkj6g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birer birer açıldı pencerelerim

birini yıldızlar geceler kapladı

birinden kışlar belirdi

birinde renkler dağıldı

pırıl pırıl.

Sesler geldi bir yerden

bir bahçeye bahar indi

bahar.

Ve bütün pencerelerim sana açıldı

birer birer aralandı kapılarım

birinden çocuk rüyaları boşandı

birinden dost yüzler

birinden ecel sakisi yürüdü

kadehinden güzelliklerin sırrı

bir damla yakut

dudaklarıma damladı

ve bütün kapılarım sana açıldı.

Birer birer kapandı pencerelerim

birer birer kapandı kapılarım…', 'Birer birer açıldı pencerelerim birini yıldızlar geceler kapladı birinden kışlar belirdi birinde renkler dağıldı pırıl pırıl. Sesler geldi b...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 9, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Klasikleri","is_hero":true,"total_lines":19,"source_url":"https://www.antoloji.com/pencereler-ve-kapilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Tane Daha', 'bi-tane-daha-bedri-rahmi-eyuboglu-5w00v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu yürek, kahpe yürek, yetim yürek, yoksul yürek

hani şu uzun havalarda, bozlaklarda, mayalarda

iflah olmaz türkülerde tüten

hani şu insanı kahreden canım

kurşun misali delip geçen

kurşun misali çöken

bu yürek, yetim yürek, yoksul yürek

binbir yerinden yaralı, binbir yerinden yamalı yürek

bir yanı tanrı, bir yanı kul

bir yanı tezek, bir yanı gül

bizim insanlarımız oğul ne zaman gülecek? 

bu yürek, yetim yürek, yoksun yürek

varımız, yoğumuz, malımız, mülkümüz, sermayemiz

canevine konan ilk taş

canevinden uçan ilk kuş

bu yürek, yetim yürek, yoksul yürek

bir yanı gül, bir yanı tezek

bizim insanlarımız oğul ne zaman gülecek? 

ağlamak ayıp değil kana kana

ama gülmeyi unutmuşlar yüzlerine baksana

o canım sevinç pırıltısı düşmüş gözlerinden

paramparça, tuz buz

bizim insanlarımız böylesine karagülmezse

birimizden biri suçluyuz

peki neyleyip nidelim

alıp başımızı limon misali avuçlarımızın içine

kara kara düşünelim

bir ilimiz var adı Rize

durup dururken bir bardak çay sundu bize

Rize’de çayı kim yetiştirdi Rize’de

Missisipi’ye karışan çayları öğretirler bize

Rize’de çayı kim buldu Rize’de

kimdi o sessiz sedasız 

kumral kumral demlenen mübarek adam

adını öğretmediler bize

işte o güzel adamdan bre şahin aman 

bi tane daha

şu dağın başında bir top gül vardı

eşi görülmemiş bir top gül katmer katmer açardı

kırk bin köyde kırk bin umut

kırk bin köyde kırk bin tomurcuk

kırk bin adet meyveye vurmuş fidan

köy okullarımıza nasıl kahpece kıydılar anlatamam

hey gidi mangal yürekli Tonguç baba

köy okullarımızı kilim misali ilmik ilmik ören

adını kaç aydın koydu acaba

mangal yürekli Tonguç baba

sana Anadolumun her yanından

kekik kokan, keklik kokan, Cevat Şakir işi

kınından çekilen kılıç gibi bir merhaba

bir mangal yürekli Tonguç baba yetmedi bre şahin aman

bir Tonguç baba daha

pırıl pırıl bir Karacaoğlan

bir Dadaloğlu, bir Pir Sultan

dilimize düşen ilk mübarek cemre

bitip tükenmeyen Yunus Emre

biz dünyadan gider olduk demiş kalanlara selam olsun

ama hep böyle gidecekse bu dünya canım Yunus 

topumuza haram olsun

gözünün nurunu sevdiğim koca Sinan

on parmağı on ulu çınar misali her yandan yükselen

dünya durdukça duracak olan

gecekondular mı gelecekti arkandan

bir kara Sinan yetmedi bre şahin aman

bir Sinan daha

bir tren kalkıyor Haydarpaşa’dan

gözyaşları yoncadan Eminem

öfkeleri meşeden

bir tren kalkıyor Haydarpaşa’dan

dünyanın en güzel treni

ağzına kadar Mehmetçik yüklü

lokomotifi pala bıyıklı

vagonlarda bir telaş bir kıyamet

Memetçik Memet, Memetçik Memet

bir tren kalkıyor Haydarpaşa’dan

tren değil bu bir hışım

ilk Türkçe dersimi ondan almışım

Memetçik Memet

Türkçem kadar güzelsin diyen büyük usta

Nazım Hikmet

bir Nazım Hikmet yetmedi bre şahin aman

bir Nazım daha

kırmızı gülün alı var

kolay kolay gelir miydi bir Mustafa Kemal

bir Mustafa Kemal yetmedi bre şahin aman

bir Mustafa Kemal daha

bu Anadolu var ya bu Anadolu

bu misli menendi görülmemiş cömert ana

bu her yanı meme, bu her yanı dudak, bu her yanı gül

bu zırnık almadan veren habire veren yediveren gül

bu Anadolu var ya bu Anadolu

bu üç yosma denizde üç defa ıslanan

gürbüz ırmaklar ortasında susuzluktan çatlayan

bu Anadolu var ya bu Anadolu

bu sapsarı sıtma, bu masmavi gurur

ne tosunlar doğurmuş ne tosunlar

bak daha neler doğurur.', 'bu yürek, kahpe yürek, yetim yürek, yoksul yürek hani şu uzun havalarda, bozlaklarda, mayalarda iflah olmaz türkülerde tüten hani şu insanı ...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 9, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":97,"source_url":"https://www.antoloji.com/bi-tane-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Geldi', 'huzun-geldi-bedri-rahmi-eyuboglu-xubd9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türküler bitti

Halaylar durdu

Horonlar durdu

Al damar, mor damar, şah damar sustu

Bahçeler put kesildi birer birer

Meyveler salkım saçak taş.

Bir bulut uçardı

Başı boş bedava

Yandı kül oldu.

Hüzün geldi baş köşeye kuruldu

Yoruldu yüreğim yoruldu.

Ağaç büyür arkasında koşamam

Kervan yürür peşi sıra düşemem

Yıldız akar uçsam da yetişemem.

Hüzün geldi baş köşeye kuruldu

Yoruldu yüreğim yoruldu.', 'Türküler bitti Halaylar durdu Horonlar durdu Al damar, mor damar, şah damar sustu Bahçeler put kesildi birer birer Meyveler salkım saçak taş...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 9, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":16,"source_url":"https://www.antoloji.com/huzun-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusura Bakma', 'kusura-bakma-bedri-rahmi-eyuboglu-4oum7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kusura bakma

İçinde bulunduğum an

Bir yarın geçmişte neyleyim

Gelecekte öteki yarın

Zaman dediğin hasba üç ayaklı

Birinin canı ötekinde saklı

Şu anın canı gelecekte

Geleceğin canı geçmişte saklı', 'Kusura bakma İçinde bulunduğum an Bir yarın geçmişte neyleyim Gelecekte öteki yarın Zaman dediğin hasba üç ayaklı Birinin canı ötekinde sakl...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 9, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":8,"source_url":"https://www.antoloji.com/kusura-bakma-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nen Var Kardeşim', 'nen-var-kardesim-bedri-rahmi-eyuboglu-wn9yk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir salkım üzüm bir bardak şaraba

ne kadar benzerse

bir nefes tütün bir demet yaprağa

ne kadar benzerse

nen var canım kardeşim? 

her nefeste biraz daha buğulanıyor cam

hep bir buzlu camın arkasından

bakıyormuşsun gibi geliyor yüzüme

çıldıracam

iki nokta bir benek gözlerim

erimiş uzanmış dökülmüş ellerim

nen var canım kardeşim? 

hay camına camekanına büyüsüne buğusuna aldıranın

kırmak mı dedin

kırmayanın..', 'bir salkım üzüm bir bardak şaraba ne kadar benzerse bir nefes tütün bir demet yaprağa ne kadar benzerse nen var canım kardeşim?  her nefeste...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 9, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":15,"source_url":"https://www.antoloji.com/nen-var-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Dair', 'olume-dair-bedri-rahmi-eyuboglu-6hfal', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümü zararsız bir mahlûk haline getirmek istediler

………………………………Göz yaşını icat ettiler.

Kimisi tuzunu az buldu kimisi çok,

………………………………Velhasıl beğenmediler.

Ölüme kardeş gibi ısınmak istediler; 

Kabristanın tuttular elinden

Şehrin orta yerine getirdiler,

Taş üstüne taş kodular

Üstüne nakış oydular.

Serviler açıldı orta yerinden

İçerisine rengârenk kuşlar

Yemyeşil dualar dolduruldu.

Ölüme kardeş gibi ısınmak istediler.

Şiiri seferber eylediler

Dolaştı asırlarca mısralar kabir kabir

Salındı servilerden yiğit besteler

Şiiri seferber eylediler

Ve elbirliği ile

Gökyüzünün en münasip katında

Mükemmel bir cennettir kuruldu

Ve üzerimize güller

Mezkûr cennette har vurup harman savurdu ölüler.', 'Ölümü zararsız bir mahlûk haline getirmek istediler ………………………………Göz yaşını icat ettiler. Kimisi tuzunu az buldu kimisi çok, ………………………………Velh...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 9, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":22,"source_url":"https://www.antoloji.com/olume-dair-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elemtere Fiş', 'elemtere-fis-bedri-rahmi-eyuboglu-n2t6a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elemtere fiş

Kem gözlere şiş

Benim bir yarim var müthiş

Bazen yedi yaşında bazen yetmiş

Elemtere fiş

Kem gözlere şiş

Benim bir yarim var müthiş

Azcık rum azcık kürd azcık ermeni

Aklına esmeye görsün.

Galata kulesinin

Tepesinden atar beni

Sonra benden önce iner, tutar beni

Elemtere fiş

Kem gözlere şiş

Benim bir yarim var müthiş

Yarısı imam yarısı keşiş

Misli menendi görülmemiş

Her parmağında bir marifet

Hünerli mi hünerli

Ayıptır söylemesi

Hemi Galatasaraylı hemi Fenerli', 'Elemtere fiş Kem gözlere şiş Benim bir yarim var müthiş Bazen yedi yaşında bazen yetmiş Elemtere fiş Kem gözlere şiş Benim bir yarim var müt...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 9, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":21,"source_url":"https://www.antoloji.com/elemtere-fis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '7 Tane Erik Ağacı', '7-tane-erik-agaci-bedri-rahmi-eyuboglu-nonvl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boş ver kafiyelere Reyis

Boş ver şiir yazmaya evlat

Otur da doğru dürüst

7 tane erik ağacının hikayesini anlat

Evimiz deniz kenarındadır Fındıklı’da

Ekmek paramız Beyoğlu’nda çıkar

Beyoğlu’na bir yokuştan çıkarız yirmi senedir

Yokuşun ortasında bir arsa

Arsanın ortasında yedi tane erik ağacı

Saydım yedi tanedir

Ne zaman yolum düşse

Erik ağaçlarını arar gözüm

Ya kedi yavruları gibi sırıl sıklam

Ya buram buram bahar içredirler

Ya bütün dalları kırılıp dökülmüş

Her sene kırılır dallar adettir

Bu yaz geleceğine alamettir

Yaz geliyor demektir yokuştan paldır küldür

Yoğurtçusu, dondurmacısı, çavuşu, yapıncağı kütür kütür

Yaz geliyor demektir çok şükür 951 senesinin baharında

Kestiler yedi tane erik ağacının yedisini birden diplerinden

Henüz yeşermeğe başlamışlardı çıtır çıtır

Körpe bir salatalık yeşili inceden Islak, nemli, ümitli

Yedisini birden kazımışlar köklerinden

Saçlarından tutup birer birer

Yedisinin de köklerini sökmüşler

Şimdi onların yerinde cascavlak

Ensesi ceketinden iki parmak dışarda

Üç katlı tombalak bir apartman kuruldu

Güzel bir yapı olsa içim yanmaz

Yapı değil mübarek hacıyatmaz

Yağlı bir çift tavla zarı

Bir yanı kumbara bir yanı kasa

Elveda benim her mevsim dalları kırılan

Sıska çelimsiz

Ama son yaprağına son eriğine kadar cömert erik ağaçlarım

Ne zaman yolum düşse

Gözlerimi yumup sizi hatırlayacağım.', 'Boş ver kafiyelere Reyis Boş ver şiir yazmaya evlat Otur da doğru dürüst 7 tane erik ağacının hikayesini anlat Evimiz deniz kenarındadır Fın...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 9, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":38,"source_url":"https://www.antoloji.com/7-tane-erik-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Türküsü', 'deniz-turkusu-bedri-rahmi-eyuboglu-a2s1j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz dediğin bir tarladır

Gülü gül, dikeni diken, tohumu tohum

Toprak gibi verimli, toprak gibi cömert

Betine bereketine kurban olduğum

Deniz dediğin bir tarladır

Uçsuz bucaksız bir tarla

Göbeği insanlarla kesilmiş

Çilesi insanlarla

Deniz dediğin bir tarladır

Sözü pek, eli ağır

Dost gibi güldürür insanı

Dost gibi ağlatır.

Deniz dediğin bir tarladır

Anadır, babadır, kardeştir

İnsan eline hasret

İnsan eli değer değmez ürperir

Binbir yerinden çatlar sevincinden

Nesi var, nesi yok çıkarır verir,

İnsan eli değmemiş denizlere bir damla alınteri

Bulutlar dolusu rahmetten mübarektir.

Deniz dediğin bir tarladır

Bulutlar, güneşler dibindedir

Geceler gündüzler dibindedir

Yıldızlar mevsimler dibindedir

Zifiri karanlık güller açılır dibinde

Bağlar, bahçeler kat kat, katmer katmer, deste deste

Bağlar, bahçeler zifir karanlık güller

İnsan eline hasret beklemekte.

Deniz dediğin bir tarladır

Kapılar açılır içinde kapılar

Bitip tükenmeyen bereket kapıları

Balıklar akıp gider bölük bölük tabur tabur

Alı al moru mor sarısı sarı.

...

Deniz dediğin bir tarladır

Üstünde başı boş rüzgâr

Gönlünce at oynatır

Üstünde bir avuç tuzlu köpük

İçinde milyonlarca yürek

Milyonlarca öpücük

Bir insan eli arar konacak

Bir insan eli muhkem, sıcak

Hey benim

Boydan boya cömert denizlerle çevrili

Güzel memleketim

Bu yaz tenha denizlerinde yıkandım

İnsan eli değmemiş ormanlar gibi vahşi

Dağ başında unutulmuş küçük kundaklar gibi yetim.', 'Deniz dediğin bir tarladır Gülü gül, dikeni diken, tohumu tohum Toprak gibi verimli, toprak gibi cömert Betine bereketine kurban olduğum Den...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 9, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":48,"source_url":"https://www.antoloji.com/deniz-turkusu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Tükenir', 'can-tukenir-bedri-rahmi-eyuboglu-sa8b0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimse bilmez can nerdedir

Can tükenir can tükenir

Saçımın telinden sızar

Gözümün ferinden uçar

Can tükenir can tükenir

Her korku zerresinde ziyan

Her kımıldanışında yaprak

Can tükenir can tükenir', 'Kimse bilmez can nerdedir Can tükenir can tükenir Saçımın telinden sızar Gözümün ferinden uçar Can tükenir can tükenir Her korku zerresinde ...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 9, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":8,"source_url":"https://www.antoloji.com/can-tukenir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüm Yeşili', 'uzum-yesili-bedri-rahmi-eyuboglu-ujm6t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel benim üzüm yeşilim

Yandaki zeytine gidelim

Gel benim üzüm yeşilim

Çam ağacına gidelim

Zeytinin rüzgarı tir tir

Çam ağacınınki pir pir

Benimki oldum olası delidir

Gel benim üzüm yeşilim

Nar ağacına gidelim

Gel benim üzüm yeşilim

Trabzon üzümüne gidelim

Gel benim üzüm yeşilim

Yeşillerin gönüllüsü

Yeşillerin durucusu

Haydi bakkala gidelim

Bir kilo üzüm alalım

Torba kağıdına girmeden

Yürü çeşmeyi boylayalım

Yıkansın üzüm yeşilim

Sonra salkım almalı

Çarşının içine dalmalı

"Var mı" "Var mı" diye sormalı.

Üzümün böyle derlisi

Yeşilin böyle toplusu.

Gel benim üzüm yeşilim

Haydi maviye gidelim

Biz değmesek

Mavi küser

Mavi bizsiz ne halteder

Gel benim üzüm yeşilim

Yeşillerin en nazlısı

Sen üzümün yeşilisin

Üzüm olman şart değil

Bir çok dallara konarsın

Hatır sualler sorarsın

Gel benim üzüm yeşilim

Seninle Bedros´a gidelim.', 'Gel benim üzüm yeşilim Yandaki zeytine gidelim Gel benim üzüm yeşilim Çam ağacına gidelim Zeytinin rüzgarı tir tir Çam ağacınınki pir pir Be...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 9, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":37,"source_url":"https://www.antoloji.com/uzum-yesili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berducesi-1962', 'berducesi-1962-cahit-zarifoglu-7k3lr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'a

Dehşetli üşüyor

ansızın gözbebeklerinden alaturka kurtulmuş

yoksa saçları bütün saçları dünyaya akıyor

aksarayda ve üç kulaç derinde

beklemek daha başka sırtüstü yatıyor

bütün azaları kirlenmiş

günahlarından işlenmiş apayrı tüyleriyle

kızlığından tavşan dokunulmazlığı bir sahne mutlaka

ve galiba

karnının bir bölümünden sonsuz ürperiyor

topyekûn bahriyeden ve murtazadan

çırılçıplak saçlarıyla gizleniyor

delikanlı kucaklardan hoşlandığı kadar

derin yataklarda anlaşılmış

haydarpaşadan binip kurtalanda

trenden iner gibi bir kız

beklemek daha başka şey

sen benim kızlığını bildiğim

kiliselerden kaçmış yağmur gibi gözyaşlarınla

minareler gibi tutuldun

sır vermez dip odalarına atıldın kahramanlığın

      başkalarına kalırsa her an dokunulmaktasın

bunca tanışıklığımız varken

sana dair

bana söz düşmüyor eğer düşerse benimle kutsaldır

     buna rağmen

başından bir maceradır geçmiş

bin türlü makam geçmiştir derim

b

yaratılmanın bir yoksulluğu da gereklilik

bir de

öğünmüş gibi değil oysa kuşların

ikimizi gece yirmi dört cephelerinde gözlemesi ustalıkla

yüzde yüz bir tanımazlık sorunu

her yanın dudaktır üstün bezelye taneleri

senin kır çiçekleri ayarında laleliğin

mayland''da hiç ama aşk değil

      bir tutam göz ağrısı

      aşk değil

kana bulanmış bir yürek

bir etek serüveni

sonuç zavallı ilkbahar giyotinleri

güneşin ilgisiz damarlarıyla yapayalnız bir keder

      sendeki santa luçiya gözleri

      benimkisi harzemşah

c

saygılı dudaklarınla yarıştım

ince bir ilgi yaşadım kıvranışlarında

gözlerinde ''harikulâde'' yaş bulutları

Yürek safındaydım sen bin mil uzaktan koska

göz değil aşk

aşk değil bin çeşit göz

bunca çıldırdım hem ilgisiz

koridor görüp ölüyordum

çizmeli tülbentli kız

saçlarında yirmi yedi yıl lodos

laleliden otobüse biniyor

kimbilir nerede oturuyor

her çizgisi ezmeyle bilenmiş

üç ''aziz'' bakışını yakaladım

bin yıldır cephane taramış

hep blek börd bir gözdeyiz

sıra kimin

benimse - rölans', 'a Dehşetli üşüyor ansızın gözbebeklerinden alaturka kurtulmuş yoksa saçları bütün saçları dünyaya akıyor aksarayda ve üç kulaç derinde bekle...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":65,"source_url":"https://www.antoloji.com/berducesi-1962-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamak', 'anlamak-cahit-zarifoglu-gmq4w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen anlıyorum,

bazen anlamıyorum.

annemi,

babamı nenemi

annem şöyle der

göstererek beni:

cin gibi maşallah

cin ne demek? 

gibi ne demek? 

babam diyor ki

bana bakarak:

altını üstüne getirmiş evin.

hiç yapabilir miyim 

dediklerini? 

ninemse der bana:

topaç gibi

bir dedem açık insan

pek de zeki.

dilinden bal akar.

attaya gidelim der.

al sana şeker der.

göz kırpar.

okşar.

sever.

bir de gıdıklar.

dedemi çok anlıyorum.', 'Bazen anlıyorum, bazen anlamıyorum. annemi, babamı nenemi annem şöyle der göstererek beni: cin gibi maşallah cin ne demek?  gibi ne demek?  ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":26,"source_url":"https://www.antoloji.com/anlamak-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şekiller', 'sekiller-cahit-zarifoglu-auaai', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'karanlık basmadan ovalarıma

kainatın duru illetsiz aydınlıkları

katılaşırken çocuk ruhlarında

karanlık basmadan kararmadan taşıtlar

et kemik taşıtı tam da

mayalanmış yüreğimin hamuru

ve ne yakıp kavuran

yaklaştırmayan kalıplara

hiçbir daraban olmadan

ziynetli topraklara da

yanardağ akıntısı yer cazibesine mermut akan lav

katiyeti heybetiyle

akıp

dağ''la terbiyeli bir insan eli olan elinle şekillenmeye hazırken

NEREDE BULABİLSEM SENİ

yetişip dizüstü düşebilsem eteklerine

karanlık basmadan

dünyayı kapatan karanlık

elimizde kılınç

ben ince işler ustası musa

kardeşim ya ki heybem

değişince kubbeli evim

girdabım -

tövbem

kapımın önünde akan ırmak

en zengin denizcisi incilerin -

uzak şarklara yollanan elçilerin

kelimeler

okyanusla yarenliğe dalıp

çoluk çocuğu unutacak kadar bol ve bereketli

binlerce yılçün kurulmuş

bir zemberek içimizde

ağzımıza boşalttı onca sözden

birinin heybeti ve lezzetinden

damağımız çatlamakta

ya ani karanlık

''inanana rahmet

inaçsıza esef'' olan

(hiçistanda

bir rüzgar belirmiş

kulağımıza gelir

bir ey muhalif rüzgar ki oyropeiş örneği

hafifçe terli bedenin krondeli

göz dikmiş duyduk ki

meni yataklarına bile) 

/japonya büyür büyür bir gün

toprağını denize yayarak

peygamber sözüne ordan hizmet olur/

kucak açanlar kadar geniş istekli

göçüp gelenler kadar hafif

az''la doyan yük olmadan

ve başlar

kimin yüreği daha yüce yarışı

musa kardeşim ağlamaktan mı

okumaktan mı az uyumaktan mı

kan gölü gözlerin

her an karanlığını giyinecek gibisin

ne kadar uzun sürüyor

ta içinden gözlerine gelmesi dikkatin

karnın ne kadar küçük ve içerde

ince belin

fazla kabarık değil kemiklerinden etlerin

biliyorum ancak sen

bu kadar yetindikçe ve ekmeği

böyle mübarek tuttukça

doyar karnı çinin hindistanın amerikanın

sen olabilirsin çaresi

su içinde

susuzluk hissinden ölen kimselerin

musa kardeşim haya''dan mı

boyuna posuna güzelliğine rağmen

hafifçe kıvrık omuzların

hafifçe eğik başın

hele terazi tutuşun

zarif

sapasağlam

ve artık

en insansız çölde

tek başına kalsa bile

eğilmezken adalen bile

yine de

bir nebzesini tutsa yüreğindeki tartarkenki dikkatin

ikiye yarılır bir su aygırı

ve çocuklar tuz yalarken çocuk avuçlarından

NEREDE BULABİLSEM SENİ

baba bıçağını ağır ağır çekerken

YETİŞİP

ana dalgın ve su dibinde yürür gibi

DİZÜSTÜ DÜŞSEM ETEKLERİNE

ana dalgın ve su dibinde yürür gibi

üzüm tiyekleri ceylan dolu etekleri

1

çocuklar

kurtulamazlar yanaklarına konan yaradan

olmadık anda bırakılırlar

sonra

nice sonra

hatta bazen karanlıklarına uzanırken kadar sonra

üzerinde gözyaşı izleri

senelerin izleri ile yol yol kalmış yanakları

mahzun yayılır

ancak görünür güzel dişleri

ve ''kuşlar da kaderle uçar''', 'karanlık basmadan ovalarıma kainatın duru illetsiz aydınlıkları katılaşırken çocuk ruhlarında karanlık basmadan kararmadan taşıtlar et kemik...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":103,"source_url":"https://www.antoloji.com/sekiller-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kuş Olur Gidersin Bir Trenle', 'sen-kus-olur-gidersin-bir-trenle-cahit-zarifoglu-n8wl9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'uzun bir geçmişimiz var 

hiç yorulmadan 

en azından bir kere 

eğlenceli beşik

ha biz varız 

ha biz maskeli balo 

saygıya durup üstün bir gecede 

bir sır payı katlayıp 

sade bir kahveden 

keyifsiz bir detayın hükmüyle 

ha biz yokuz 

ha biz seferde

ya bu kez ölenleri görmeliysek 

ya sen kuş olup gitmeliysen bir trenle

parka dolalım 

park bizi alır önce 

seyrimizden bir sabah kazanır 

eğri fakat daha çok eğrilmez bir şoförle 

sayısız rampaya katlanır 

ya güneşten daha zengin 

sofraya diz çökeriz 

ya sen kuş olup gitmeliysen bir trenle

oysa sergimize kuşlar gelir uzanır.', 'uzun bir geçmişimiz var  hiç yorulmadan  en azından bir kere  eğlenceli beşik ha biz varız  ha biz maskeli balo  saygıya durup üstün bir gec...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":23,"source_url":"https://www.antoloji.com/sen-kus-olur-gidersin-bir-trenle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-cahit-zarifoglu-82p2v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaklaşan seherle sözlüsün. Bir zamanlar 

Dağ Taş ve toz toprak karlı yollar 

Ve buzullar arasında çağlayan sularda 

Aracıydın ekmeğine sevgili eşlerinin ve çocuklarının 

Evet  barışlasın bütün zamanlar 

Dar sessizliğe bu dağlar

Bir yamaç kaymasını omuzlarsın yıllarla 

Biz ne gülücükler biliriz senden 

Ne rahmetler açıldı senden bize', 'Yaklaşan seherle sözlüsün. Bir zamanlar  Dağ Taş ve toz toprak karlı yollar  Ve buzullar arasında çağlayan sularda  Aracıydın ekmeğine sevgi...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":9,"source_url":"https://www.antoloji.com/baba-463-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Ol Böyle Söyle', 'boyle-ol-boyle-soyle-cahit-zarifoglu-96p9d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğuyor çocuklar 

Türkiyede 

Cezairde 

Kenyada 

Eskimolar ülkesinde

Dünya ne uzun 

Ne kısa

Milyarlarca  milyarlarca çocuk 

Geldi yeryüzüne 

Her birinde bir çift göz 

Baktılar yer-gök aleme

Şimdi gözler 

Eğleşir  eşyada 

İki kere milyarlarca gözle 

Baktılar nehirlere 

Yanyana akıp 

Karışmayan 

Tuzlu suyu tatlı suya 

Kuşlara 

Dağlarda dolanan kartala

Şurada bir savaş var kan akıyor 

Şurada. İki kere müslüman kan

Ve milyarlarca çocuk 

Tarih boyunca 

Büyüyüp 

Avuçladı dünyayı

Giderken 

Bıraktılar hep

Doğuyor çocuklar 

Çinde 

Afganistanda 

Türkiyede 

Şimşek sabahta yıldız gecede 

Doğumlara artık ebeler 

Anneler de karışmıyor

Ya bu sonbahar 

Dünyanın mevcudu ne 

Nereye gitti 

Doğup doğup boy atan nağra atanlar

Ne sesleri kaldı 

Ne cisimleri

Ah çocuklar çocuklar 

İçiniz kararmasın sakın 

Açıp 

Okuyunca bu şiiri

Şimdi biraz 

Baksın dikkatle bana gözleriniz

Ögrenelim şu duayı 

Yol boyunca 

Beşikten başlayıp 

Mezarlara kadar

Önce besmele 

En güzel kelime

Allahım 

Yol boyunca 

Bırakma elimi 

Düşerim sonra

Allahım 

Niçin halkettinse beni 

Kalbime söyle iyice 

Engellerden arınsın yolum

Allahım 

O güzeller güzeli 

Hangi iyilik diledi senden 

Dilerim ben de öylelerini 

Allahım 

Peygamber efendimiz 

Hangi şerlerden sığındıysa sana 

Upuzak tut benden de onları

Allahım 

Yol boyunca 

Tarih boyunca 

Başıboş bırakma bizi', 'Doğuyor çocuklar  Türkiyede  Cezairde  Kenyada  Eskimolar ülkesinde Dünya ne uzun  Ne kısa Milyarlarca  milyarlarca çocuk  Geldi yeryüzüne  ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":73,"source_url":"https://www.antoloji.com/boyle-ol-boyle-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Gök Orda Mı', 'mavi-gok-orda-mi-cahit-zarifoglu-48inf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakıyorsunuz kuşlar 

Hazır 

Sokak lambaları yanık unutulmuş 

Bir kadıköy vapuru hınca hınç insan 

Çok geçmeyecek 

Martılar beyhude turlar atacak 

Kıyılar lağım konserve kutuları 

Mısır koçanları

Sevgi aranabilir yine 

Korkusuzca say koskoca kederlerini 

Bir kuyu bulunabilir

Aklımdan çıkmıyorsun 

Sen hala dizüstü 

Bunca anıyı besleyerek 

Sokaklarda avaz avaz konuşarak kendi kendinle 

Mektupları öpebilirsin kırmızı dudaklarınla 

Görür gibi olarak açıp baktığımı 

Bense şöyle diyorum: 

Buradan bir acı kanamış boyuna

Kuşlar hazır 

Öncü havalanmak üzre 

Şehri gelen bir mevsime bırakıyorlar 

O vapur hala hınca hınç 

Kimbilir herbiri hangi dünyaya sağır 

Çok geçmez aradan

Kadınlar kapı önlerinde 

Ellerinde meşalelerle 

Aydınlatırlar gelip geçen erkek suratları 

Yorgun bir sarıyla ben de 

Geçeceğim önlerinden

Aklımdan çıkmıyorsun dedim 

Başka türlüsünü yorgunum anlatmaya 

Telefonlar yan hücrede çalışıyor 

Bende kurşuni bir dere 

Ağaçlar hayvanlar bile kaygılı 

Onu bir mersedesten indirdi kalçasına kadar 

                                                          açılarak

Yapayaşlı bir rum kadın 

Herşeyde yanıp sönen bir kıyamet algısı 

Haydi koşayım diyorum belki dağılır 

Koşuyorum 

Sancağımda kendi rüzgarımla ölgün kıpırtılar 

Hayır daha sevgili daha sevimli değil 

Ne başka bir gün ne başka bir zaman

Çok geçmeyecek aradan 

Şöyle diyeceğim: 

Bulutlar açmadı 

Mavi gök orda mı', 'Bakıyorsunuz kuşlar  Hazır  Sokak lambaları yanık unutulmuş  Bir kadıköy vapuru hınca hınç insan  Çok geçmeyecek  Martılar beyhude turlar at...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":48,"source_url":"https://www.antoloji.com/mavi-gok-orda-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahenksiz Kuşlar', 'ahenksiz-kuslar-cahit-zarifoglu-jcn72', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çayırkuşu engelsiz yapraklara 

havası dondurulmuş ve suyundan  alıkoyulmuş 

bir ay gecesi tanrısıyla 

elişi kağıtlarından ev demetlerini 

ve deniz başlarında 

küçük ve yuvarlak ellerle tutulmuş çocuk etekleri 

çayır kuşunu engelsiz yapraklara

çaçaron hep evleriyle onlara bir akşam geçidi 

vurulmadan ve korkusuna 

sebepsiz kapılmadan 

duvarlara yapılmış heykel ağızlarındaki sözlerin 

ve eski risimlerde 

yerli oyulmuş 

gözlerin ve hiçbir vehmin önünde 

vurulmadan ve korkulara

yazı sonu alınan bir kuştu 

yerle gök arasında 

kadırgalarında renk atmaz cömert çiçekler 

su altlarında ve yürek diplerinde 

zarı delinerek bir an bekleyen 

kanatları sabra 

ve kabus sonlarına 

çarpan konuşan ve sesler çeviren 

yerler gök sonlarında 

görülmeden tanınan 

ve en gerektiği yerde anılan 

civa sıcağı yurtlar 

çamdan insanı çiğneyen sakızlar 

korkuya öteye ve dünya seslerine 

çarpan çalkanan 

bir yamaçta yalnız başına durabilmiş 

açabilmiş çalılar

çayırkuşu insan ve toprak levhasında 

gagası ışıyınca durur anlatır 

bildirir ki güneştir 

her an sabah sesi çıkaran 

ve devran deyince 

insanın isim verdiği yüceden 

göğü kollayan ve ufuktan aranan 

bir çift gözü en son şekliyle 

her an bir zindan resminde çağıran 

güneştir gagası 

ışıyınca çayırkuşunun

bir savaş bütün bunlarla doludur 

ölüm beyin düzlerinde 

sık sık gezinen ve işte tamam yerine 

her dokunuşta bir delik açılan 

ve hepsi bir tek karanlığa açılan', 'çayırkuşu engelsiz yapraklara  havası dondurulmuş ve suyundan  alıkoyulmuş  bir ay gecesi tanrısıyla  elişi kağıtlarından ev demetlerini  ve...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":48,"source_url":"https://www.antoloji.com/ahenksiz-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeynep Ve Uzaktan Fırat Üzerine İkili Anlatım', 'zeynep-ve-uzaktan-firat-uzerine-i-kili-anlatim-cahit-zarifoglu-qouf4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte size söylüyorum 

Toprağın yorulacağını 

Fıratın ordusuyla kah cenge vardığını (kâh uykuya 

                                                                       varmıştır) 

Zeynebin fakir göğsü cılız bacağı 

Fırat cenge vardıkca kabarmış 

Uykuya vardıkça kırılmıştır

- Zeynep çık kuyudan 

- Ben çıkmam kuyudan

1

Kent kurmaya bir seher vakti 

Dualar ederek seyirtiyor 

Siyah yanaklı etleri barbar kabartılılar

Geliyorlar bulmaya insanları 

Kan damarlarını bağlamaya kırnaplarla

Çün içlerini basıyor halklar 

Yağma var içlerini basıyor halklar

Öykü böyle başlasın işte söylüyorum 

Önce yeryüzünde yoktunuz - bir kadın ki 

Rahminde boğmadı size annenizdir 

Buluşunuz değildir anne - doğuranınızdır 

(Anne boğmaz doğurur) 

Nasıl ki doğdunuz ve buldunuz annenizdir.. 

... Ve nasıl geçti çocuğan süreleri 

Erkeklik ve kadınlık gürlemeleri 

Bir av gibi 

Göğü mutlu bir nefes yapıp söyleyip 

Muhabbetle ölürken 

Yepyeni bir anne gerekli

En çalkantılı yönleriyle dünüm 

Mağara hummasına tutulmuş 

Gerçek mavi ırmağını 

Durmayın düşünün

- Düşünün 

  Dağların sivri döşlü bir ceylan 

  Ormanın ve kara bahtlardan korkan 

  (Vuruken korkulsun vurulanın bahtından) 

  Bağırana öfkeli yürekler 

  Şehre yürüme devleri toplayan 

  (Dağlara gitmeli ağaçlara mağaralara ne zaman) 

  Düşünün yaylaları ağız''ları dürüst çiçekleri 

  Kırları hünerli hayvanları 

  insanı hür yatırıp hür kaldıran buğday hakikatını 

- Düşünün zekanın doluluğunu - bir emanet olduğunu 

- Kullanın çocukluğunuzu 

  Bombalığını 

  Cepane damlarını 

  Diri bedenlerdeki kadınlığı 

  Erkekliğin altın çağını 

  Ki ölüm bir doku konuğu 

  Gibi durmadan geldikce ve göründükce

2

Dağda genç kadın 

Güneşe gömleğini açtı 

İncecik tüylü kabarcıklı tenini 

Kalın bir dudak gezindi ve güneş

Kentte genç erkek 

Geceye gömleğini açtı 

İnce zehirli morarmış etini 

Kalın bir akrep gezindi ve loşluk

Dağda Zeynep kadın 

Kuluncunda çıkan kızıl çıban gibi benzeri 

Doğurdu bir çocuk

Köylüler ırmağı sıvazlar 

Dururlar ay - buğday korosunda 

- Ay karınca ad konmaz oğlana 

  Mehmet kente çağrılıp 

  Afsunlanıp burgaçla kurcalandıkca 

  Yüreğinde morarmış kan vurdukca 

  Köy kararı ad konmaz oğlana 

  Heyda heyda heheyda 

Yaşamaklı başın nar gibi 

Koy belini toprağa belin çatlasın 

Sok gövdeni toprağa toprak çatlasın

Zeynep kadın genç kadın

Başı bir başka yönde 

Durur kendi dilinde 

- Mehmedim kekliğim 

  Katbekat giysilerimdir üstümde 

  Bir gün yağ kokarım bir gün bal 

  Daya Mehmedim daya dertbükülen bileğini dizime 

                                                    ev çeviren dizime 

                                                  yıldız güden dizime 

Değildir hecin yüzüne yüzüme 

Anla yüreğim bir çarpıntı bellemiş 

Anla ne demeye bellemiş 

Yorgun sığırlar 

Geceyi oldurup 

Çekip getiren koyunlar 

Evi çevirsin korkuları çoğaltsın 

Sofraya karşı bir beygir sureti vursun da 

Çocuklar sofrada bir çıra gibi yansın da 

Anla şu dağla bu dağın yanında 

Anla hayatta 

Bir gelip gelmemene yaslanmış 

Karnım bir dik bayırın 

Bir dibinde bir doruğunda 

- Bu oğlan senden olan oğlan 

  Öteki oğlan senden olan oğlan 

  Şu kız kendi kendine doğdu babasız 

  Bir kez gel çocuk gözle sen 

  Bu gece çocuk düzenleme gecesi 

  Çocuklarla sofrada yanıp tutuşma gecesi 

  Yemeği dökeni somunu hırsla kapanı 

  Kardeşinin gözüne parmak atanı bağışlama gecesi

Susunca Zeynep 

Dağdan kentten köyden kasabadan 

Bir ışık bir sıcak bir karanlık 

Bir çocuk yalvarışı bel burkulması 

Bir erkek çaprazı adele kıvranışı 

Bir zehir düşünce içine çabalasın 

Cesur cesur eşyaya dökülürken kadınlık

Köpek evin damına süründükçe 

İçeriye bir tüy ısısı uyku kaçıran sıcaklığı 

Saldıkça ve Zeynep karnını avuçladıkça 

Ve karnı değişip değişip 

Bazen bir azık çıkını 

Bir tiken çukuru 

Bir bal kutusu titreşimleri saldıkça 

Çocuk delirmiş gibi fırlar ananın sıcağından 

Deşe deşe koşmak için dağdan kentin yollarına

Çocuk Kısık kaya dibinde çarpılır 

Köpek çocukla haber salar köpek ırkına 

- Durdurun gece hücumlarını 

Artık aşk insan kalbine sığmıyor

Kentliler akrebi savuşturdular 

Bağırıyorlar güneş - ışık korosunda 

- Çocuk Mehmedin dinine bağlansın 

Ay gördükçe öfkesi ağalansın 

Aşka değdikçe gövdesi 

Nar çiçeği gibi patlasın 

Şerha şerha yarılsın 

Kurtlarla ağız ağıza verip ağlasın 

Sabahın çiğini tandır ateşinde dağlasın 

Köye gelin geldikçe toprak duvarları baltalasın 

Heheyda 

Cazgır ve enli bedenler 

Harman yerinde kütürdiye dursun 

Kıvrılmış ürkek ve atılgan 

Dağ gibi güneşe dursun 

Terleyen ve soluyan bedenler arasında 

(Damlarda seyre durmuş birbirine sokulan

Birbirine dirsek vuran köy kızlarına ait) 

salkım salkım memeler

Dügündür sanıyorsun ey güvey 

Bir gelin bulundu sana işaret edilenlerden oldun 

Bugün bir cennet hüneri kazandın 

Anan bacın kurban sana 

Toprak damlardan bir kız aldın 

Ona selalarla git 

Onu besmeleyle değiştir

Düğün 

ve işaret 

Bir baş çemberiyle atılınca 

kovalar birbirini genç kızlar 

Her gece karınlarına bir düğüm çalan 

ihtiyar kızlar kocamış oğlanlar 

Ay koşar mızrak koşar 

Söyleşir devrilir birbiri ardına 

Er - kız korosu 

- Er meydanından damdaki giysilerin içine 

  Er kazanlarından hız kazanlarına 

  İtişen bir şey oluyor 

  Künde ve dönüyor toprak evler 

  Durmadan çevriliyor damlar 

  Birbiri üstünden ve içinden geçiyor 

  Kız kadın ve çocuk yüzleri 

  İkinci üçüncü ve beşinci künde 

  Yani aynı anda sanki 

  Beş künde birden 

Ki Zeynep 

- Kız çocuk Zeynebin kaderinde kaynasın 

Ve kentten köye yalvarış 

- Biz bir insan yaylımı 

  Bir beşik hatası ekmek pazarlığı 

  Bir tarih kurbanı bir bilim yanılması 

  Köye inen aç kurtların 

  Tenekelerle ürkütülen çakalların akranı 

  Çöplerle delinen 

  Ceninlirinden bizler onarıldık

- Kentte kaykılan köy bebeleri 

  Büyüyüp de kenti bıçkın 

  Bir yürek ve lapa beyinlerle 

  Tüneklerde gece diplerinde 

  El yüz yıkanan park çeşmelerinde 

  Sabunsuz kör bıçakla sakal kazırlar 

  Bütün bir ekmekle koca bir gün savarlar 

  Köyden çıkınca kentte anlamsızdırlar 

- Konuşup türkü söyleyip 

  Pilli radyo peyda etmeleri 

  Uzayıp rursun apartman kapılarına 

  Gazete tokmaklarına 

  Geceyi nakışlı yorganlarıyla 

  Sabaha aktaran köy bebeleri 

  Ey kalın ve kocamış bebeler 

  Başlarında boncuklu takkeler 

  Pazularında topraktan bekçilerle: 

- Kız çocuk 

  Durmasın ağlasın 

  Bırak ağlasında durulsun 

  Zeynep kadın ey kadın 

  Yolun ayrı yolun ırak 

  Bir memendez bir yılan başı 

  Birinde bir güvercin yavrusu 

- Nasıl ki duyulur yamacı 

  Suyun şırıltısı 

  Kız çocuk kapanır bakraçlarla toprağa

(Birin ikincisi 

sal merhamet bulutlarını- kurut içimizdeki 

öfke mayalanmalarını)

Görenler durdular kadınlık korosunda 

- Zeynebin başı su çiçeği gibi döner 

  Ay çiçeği gibi döner 

3

Zeynep kadın dereden yükselen 

Haber dolu bir söğüt ağacını

Dallı güllü basmalarıyla karşıladı 

yol başında. Tarlaların ve otların 

arasında. Yel vurdukca söğüdün 

dalına ve yaprağına 

Ve Zeynebin karnında bir tabak açılıp kapandıkca 

Ve köy isli bebeleriyle tepelerin 

ardından koptukça 

ve çeşmelerden derelerden su yerine 

bebeler ve köpekler aktıkca 

Zeynep iki elini bastırır kalçalarına

- Ruhumuzun kirlenmesi dolmadı mı 

Gövdemizin kıvranması doymadı mı 

Bir hınzır uyku bir şeklaban uyanıklık 

Bir batında gecenin gündüzün kavranması 

Bu nedir böyle gün mü günsüzlük mü 

Hangisine kapıldık nerelere atıldık

-İşleyen demiri ve el tırpanlarını 

Onlar ne etti nasıl hamle etti 

Ruhum Kollarım Günahım sevabım 

Ölçülerek tartılacağım

- Gecelerimi ağırlıyamaz oldum 

  Yürüyorum 

  Benimle adım atan bir şey var 

  Ben fakir gövdeli yumuşak etli bir Zeynebim 

  Bir köpeğin kanı yürüyor 

  Benim kanım yürüyor 

  Dişi köpeğin karnı bir anbar 

  Benim karnım bir anbar 

  Belim bedenimi besliyor arkadan destekliyor 

  İşte iz bıraka bıraka yürüyorum toprağı 

  Dağları bayırları 

  Bir köpek miyim ki benimle 

  Soluk alan bir şey var 

  Hep köpeğimiz var yanımda 

  Çocuklarla oynaşır durur 

  Ey Mehmet nerdesin 

  Bu köpek senin yerinde

- Yoksa bu köpek ben miyim 

  Bu köpek mi benim yerimde

- Ruhum kirlenmeden soluyun beni 

  Dinleyin içimle bir soluk verdiğimi 

  Duyarsanız ben olurum 

  Köpek kendi olur 

  Bana göre değil köpeğin aşkı

- Bizi ışığıyla vuracak şimşek nerede 

  Beni ben olarak ve köpeği kendi olarak 

  Uyuyan ama dik duran heykele ne olacak kim sarsacak 

  (- Uyuyan heykele ne oldu kim sarstı) 

  / yer oynamış gibi kim sarstı / 

  Kılıç çekiyorsunuz ve uzuyor 

  Büyüyor ruhun görgüleri

- Sırtınızı köleniz sıvazladı 

  Siyah ve beyaz bilgileri sonsuz olan 

  Bir dağı bir dağdan ayıran 

  Yani bilen granit yataklarını 

  Ruhun içinden dünyaya doğru keşfe yönelen 

  Namaz vakitlerini aya ve boşluklara göre derleyen 

  Kölenize buyurdunuz bizi 

  Eğildik eteğini öptük 

  tırnağını ve avuç içlerini öptük 

  Efendim büyük efendim 

Yüzünüzden var olan hurma dallarının önündeyiz 

Yüzünüzden var olan hurma dallarının önündeyiz 

Ayın bir muhabbet armağanı olduğu vaktin önündeyiz

4

- Toprağı hazırlayınız çocuklarınıza 

  Ve çocuklarınızı ayar ediniz toprağa 

  Evi dik 

  Karnı tok 

  Kanı sağlam tutup 

  Göze savrulan toprağa

- Kadını hazırlayınız çocuklarınıza 

  Erkeği hazır ediniz onlara 

  Öyleki kadın 

  Günü saati dolunca doğurunca 

  Bin yılı birden doğursun

Sancısı bel ağrısı teri ve kanı 

Zorlanan alnı şişen şakağı kadının 

- Çocuğun yüceliğiyle avunsun

Gün gelecek 

Mızrağın ucunda yeşil renk bir tülbent 

Çemberli mermerin dibinde 

Balık yiyen balık üreten iki tülbent eri 

Balıklar ki harflerdirler 

Ağrıyan başları sürtünüp kızışan derileriyle 

Kızgın ve diklenen 

Ürperen ve aklım geçiren güçleriyle 

Yollara devlet resmi çiziliyor

Hayret ve varolma tıkandı 

Hayret ve haya tıkandı 

Hayret ve hayret ve hayret 

İlk kez geriye dönmek gerekiyor

Dağları yokladınız mı dilsiz duranları 

Bir de kulak kesilince 

Dağ konuşur - Hayır konuşmaz mı

Sonsuza dek kalmaz Fırat bu mağarada 

Tanrı elbet kanatlı halketmiştir toprağı da

Taşın kendisine mahsus bir sesi vardır 

Nasıl ki kardeşim 

Yelelerinden zor çekilen bir at gibi 

Gözü en ilerde 

Onurlu burnu kaya ve kılıcın çıkardığı kıvılcımlarla çevrili 

Gövdesinde en ince sanat gelinleri 

                      meseleli 

                     endişeli 

Koştukça hızlanan hızlandıkça hızlanan 

En eski uygarlıklarda hak arayan 

Gövdenin labirentlerinde 

Cam gibi birden donan 

Bütün bir gövde bir hayret 

Bir şaşkınlık bir taaccüp gibi donan 

Gelinleri ışığa uzayan bir at gibi 

Aşk bir at gibi 

Fetih bir at gibi 

Minyatür bir taç gibi 

Çağın ve içimizde balyoz gürültüleri', 'İşte size söylüyorum  Toprağın yorulacağını  Fıratın ordusuyla kah cenge vardığını (kâh uykuya                                              ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":332,"source_url":"https://www.antoloji.com/zeynep-ve-uzaktan-firat-uzerine-ikili-anlatim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Fantazisi', 'hasret-fantazisi-cahit-zarifoglu-gb22z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hemşeri miyiz benden saklama 

Aşina saçların 

Hele başını arkaya atışın 

Sanki yakın komşu doğuştan sürmeli gözlerin 

İliklerime kadar ürperiyorum karşında 

Aynı kentin hamurundan değilsek 

Söyle hangi bağ 

Nerdeki dostluk dolamış kaslarını boynumuza

Çoğu zaman 

Kabzasında 

İkimizin birden kavrama izleri 

Olan 

Uzun ve enli bir kılıç geliyor yanıma

Yoksa 

Göksümü kaldırarak 

Gökyüzünü doğru açtığım bağır 

Darbe üstüne darbe yiyor 

Kafa büyüklüğünde taşlarla

Doğru söyle hemşerimiyiz 

Aynı kentin hamurundan değilsek 

Nasıl kalkıyor haykırşımızdan aynı kuşaklar 

Bir gürühsa yüzüstü kapaklanıyor

Bir gürbüz vakit suç ve günah dolu 

Kaçak 

Deli dolu

Kıstırıyoruz onu bir tenhada 

Bir sen anlıyorsun bunu bir ben 

Zaten ortada bir sen varsın bir ben

Elmacık kemiklerini arıyorum buluyorum 

Çıkık 

Yüzlerini 

Pembe ve gergin 

Ellerini 

Gizli ve sıcak 

Göğüslerini 

Çöldeki sıcak

Doğru söyle çabuk söyle hemşerimiyiz 

Boşuna mı  bu kadar telaşlanışım 

Yoluna  baş kuydu şahsım 

Mırıldandığım dava yonttuğum heykel 

Vurduğum gülbank 

Bir hasret bu yağma bu soylu kıyım', 'Hemşeri miyiz benden saklama  Aşina saçların  Hele başını arkaya atışın  Sanki yakın komşu doğuştan sürmeli gözlerin  İliklerime kadar ürper...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":42,"source_url":"https://www.antoloji.com/hasret-fantazisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Camlar', 'beyaz-camlar-cahit-zarifoglu-98a1m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni bu sabah iri anla 

Taşıp

Deli deli dağlardan inerek 

Şehirlerin düzüne otumuş bir sel gibi 

Yekpare bir  suyum ben 

Kocaman sev

Şikayetim gözlerimden kim 

Ayetlerden ayırdın

Kimi vakit geldim sana 

Ama hüznüm döndü 

Baktım ki işgal gözlerin

Bilirem aydınlık için 

Karanlık da gerekli

Bazan var''ı 

Anlarsın yok ile 

Sevgilim 

Vazgeçilmez malzemem aletim 

İhtiyar cam bakıcısı 

Söyle nerde kaybuldu 

Bizimi onlarını ayırırken tuttuğun yarğı

Bilmedin bile nasıl gelindi 

Birkaç yüz sene yollar

Tırnak kadar plaka 

Programın yazıldığı

Ucunda bir kılıç 

Sonra bir kılıç ucunda bir plaka

Tırnak  kadar büyüklüğü o kadar ince 

Proglanmış Ve Bunlar Gibi 

Terzide murdar kafa biçildi 

Silindir bir şapka 

         için yontulup 

Traşlandı

Şimdi inSanSan aklını bileklerinde erit 

Gerdir yüreğinin kirişini

Fakat beni bu sabah yakın anla 

Bakarsın kapkara ve kızıl hançereler arasında 

Sesim yeleleri parlar bir at 

Paslı dilini çarpan

Sen ki şimdi hele 

Duayı erteledin 

Akşamı aradançıkardınsa bile

Çocuğuna bakmadın 

Un-ufak yapayalnız karın 

Önünde bütün varlığın bir diz''inin

Terziden sen de sen de 

murdar bir baş edindin 

camlar daha da kıvrak 

Kalb hor..', 'Beni bu sabah iri anla  Taşıp Deli deli dağlardan inerek  Şehirlerin düzüne otumuş bir sel gibi  Yekpare bir  suyum ben  Kocaman sev Şikayet...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":48,"source_url":"https://www.antoloji.com/beyaz-camlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Çocuk', 'o-cocuk-cahit-zarifoglu-i70ke', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahçeden çocuk sesleri geliyor 

  Hayatı dinliyorum 

  İçim yoruluyor, ruh yoruluyor

  Büyük gözlü çocuk 

  İnsanın içine kadar bakıyor 

  Sorar gibi 

  - Nerede benim babam

  Kendimi şöyle görürüm düşümde 

  İki ata birden binmişim 

  Biriyle kuzeye saldırıyorum 

  Ötekiyle 

  Alkan lalelerin 

  Kıpkızıl tutuştuğu sulara

  Nerede babam 

  Karşısında yapayalnızsın 

  Duvar gibi dikilen 

  Bu sorunun

  Okşuyorsun başını 

  Şehit çocuğunun

  Bahçeden kuş sesleri geliyor 

  Sabahı dinliyorum 

  Bu sefer bezgin

  Bir vakit 

  Darağaçları kurdum 

  Elimden fırlayıp gidiyor cellatlar 

  Silah olarak 

  Bir tek soru var elimde 

  Nerede babam, nerede', 'Bahçeden çocuk sesleri geliyor    Hayatı dinliyorum    İçim yoruluyor, ruh yoruluyor   Büyük gözlü çocuk    İnsanın içine kadar bakıyor    S...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":28,"source_url":"https://www.antoloji.com/o-cocuk-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saç', 'sac-cahit-zarifoglu-6gwxu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zili - siz geldiniz -pamağınız durunca 

a saçlısı biraz karşınızda 

Ama durun uzun zaman önce 

daha sizinle karşılaşmadan 

dört köşeli

kavşaktaki odada 

çook uzun daha dikdörtgen 

masa duruyor.

Korkuyu herşeyden çok orda 

Bir de zil sesinizi alınca 

Daha size banyoyu 

Havasız banyoyu açmadan 

Korkuyu götürüp kilere 

Kum torbasının içine tutuyor.

Oyuncak saklı gelişinizle 

küçük yamyam ağızlı 

yassı alnını 

her gülüşün içinde tutan 

yontma biçimiyle a saçlısı 

karşınızda hemen

a saçlısı 

daha herşeyi anlaşılmadan 

daha siz ona aydınlanmadan 

geçici bir bilardo alanında 

kuzgun hançerli 

sakal gibi el içen 

donuk 

solgun kaçışlı 

sevmeye ve sevdirmeye

bir erke biçimi geyik salmış 

a saçlısı 

durunca güvercinli kapıda 

mesela oldukça bir viyanadan 

meçhul bir bayın göğe yaslanan şapkasıyla 

elverişli çay sergisi', 'Zili - siz geldiniz -pamağınız durunca  a saçlısı biraz karşınızda  Ama durun uzun zaman önce  daha sizinle karşılaşmadan  dört köşeli kavşa...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":35,"source_url":"https://www.antoloji.com/sac-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılarıma Da Kardeş Olur Musun', 'acilarima-da-kardes-olur-musun-cahit-zarifoglu-dura7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sıcak ilişkiler adına davet alıyorum 

Biraz kan ve ilik hızlandırıcı olarak

Kardeşim dedim 

Acılarıma da kardeş olur musun

Baltasını havaya kaldırdı 

Yükselemezdi daha 

Söyledim 

- Haydi acılar haydi az daha

Dedim kardeşim 

Omuz başlarımdaki  şu yara 

Ormanların serin gölgesindeki papatya değil 

Arif bir bilinçle yürürken oldu 

Yüce buyrukla

Aaah 

Bu kadınlar kirletmiş 

Başları kara geceler içnde yolunarak 

Zindanlar nasıl dayanıyor katran duvarlar

Gebe karınların zonkuna

Kardeşim dedim 

Sıcak ilişkilir 

İşte çagrıyla çatlayan damar 

Gövde sinir urganları kaçı olarak

Bir göz yaşı gibi 

Sarktı dolandı kalpağrısına leylaklar', 'Sıcak ilişkiler adına davet alıyorum  Biraz kan ve ilik hızlandırıcı olarak Kardeşim dedim  Acılarıma da kardeş olur musun Baltasını havaya ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":24,"source_url":"https://www.antoloji.com/acilarima-da-kardes-olur-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazı Özlemler', 'bazi-ozlemler-cahit-zarifoglu-ewizh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağlara vardık 

Herbirimizin elinde gözleri ışık saçan birer deve 

Düşündük ayaklara düşmüş kıymetlerini iade ettik 

Sandık 

Dervişlerin

Modern salonlar koltuk takımları büfeler 

Baş köşede sadece bakılan bir şamdan gümüş bir sürmedenlik 

Düşündük ayaklara düşmüş kıymetlerini iade ettik 

Sandık 

Anne çehizlerinin

Sevgililer kapadı toprağını 

Çocuklar ne kadar hırçın 

Alışverişten dönüyorlar geceleri 

Babalar gözlerini dikmiş sanki kutsuyorlar şişeleri

Hepsi bir tek haftada değişebilir: 

Dağa gerçek bir gezi 

Ellerde yekpare bir deve sakin tabii renkte gözleri 

Dervişlik kılık kıyafetten ayrılalı beri 

Kim bilirse ki alıp verilen soluklar yalnız değil 

Herşey bir tek haftada

Başla deyince başlayabilir 

Evler eşyaları atıp insanları çağırabilir 

Bir bakarsın ki kadınlar gizlice hafifçe sürmeli gözleri

Sevgililer yayar topraklarını 

Delikanlılarda 

Boyunlara kadar kızartan damarların 

Açılır ilmikleri

Bir vakit diye anlatılır o zaman 

Dağ ve şehir diye bölünmüştü insan 

O dar buran gavur giysiler 

İçlerinde kopralar göğüsleri sıkılıp duran 

Ayaklar cepler kafanın içi, elin edip tuttuğu bir mezbele 

Bir tek kalp temizce  ve sinmiş 

Taşırdı kamburu taşırdı kamburu

Bir vakit gelse de acıyla / Hatırlansa zorbela / 

                                                         Anlatılsa', 'Dağlara vardık  Herbirimizin elinde gözleri ışık saçan birer deve  Düşündük ayaklara düşmüş kıymetlerini iade ettik  Sandık  Dervişlerin Mod...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":36,"source_url":"https://www.antoloji.com/bazi-ozlemler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesaplanmadan Ölü', 'hesaplanmadan-olu-cahit-zarifoglu-uixwi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1

Onlardı uzak yerler seçtiler 

ve sayesiz ilahları 

Kalın ovalar kuşları yaklaşan ağaçlar 

ve taşlaşan boğulu kalan nağra 

bir sarnıç kemeri eğrisinde 

dünden bugüne seyirten 

telaşşız sular seçti padişah buyurdu kervansaraylar 

hudutta kraliçe ağızları serhatte yagız duşlar 

ipe saldıran yığınlar çün osmanlı kanları 

melekmeşen at yangınları 

ülkeyi kol gezen projektör bakışlar 

hayvanlar bile altında rahat uyuyan 

ve elgizin göğsünde kışlık bahçeleri 

ağırlaşan bir çiçekte 

sultan sıcaklığına çarpıp 

ummana sıçrayan çekirgeler 

aşk donanmış bir havada 

şahadet getiren sedir ağaçları gemilerin 

el çırpan iskele ve sancakları 

-Üzülmek fethedilmiştir kışladan haber 

tevrattan sakıncalı sözler sakınmak gereken göz 

gerek kanatılan gelinler 

davulun orta yerinden bir baş soğan 

katlayıp ince ağızlarında çingen 

içlerin boşalan surlarına zurna

Toplanan şimdilik sürgüne eklenen 

değerli çocuklar 

arkalarında büyük rüzgarlı anne etekleri 

ucuna takılan yaşmak çeşitleri 

mavi çok renkli tülbentler 

iri gözyaşı boncukları 

içine kainatlar sıkışan 

caminin yürek konmamış kayalıklarında 

durmadan her lahza yeniden arınan 

henüz bir böceklik yer açılan

elleri aynı kumaytan 

içlerinde bir haremi tavşan 

açık duran kapılarının arkasında 

çocuklar baştan sona kadınlara düğmeli 

bu bir an yüzümü hayvanlara dikip 

çamurlu 

-Ey babilin yorumaz artıkları

dışımda açıkça bir tazı koşuyor 

ölümlerde yorulup 

bir güle kapanan 

gelincikte bekleşen

2

sonunda ak tavşan ölüme benzeyince 

koşup bir ölümün önüne titremeler içinde 

diz çöken adamlar beynime atıldılar 

ağırlıkları safra taşları yanlarında 

bellerine kancalı tırpanları

saçaktan akan buz parçaları 

ona birazda ben katılacaktım 

çünkü herhangibir hazırlık yapmışlardı 

taş duvarın dibindeydik ölümünden 

ses çıkmasın beni kapıyorlardı bedenleriyle 

alnımı bana bıraksınlar 

hiç yalnızlık korkutmayan alnımı

karnımdaki boşluklara 

saçlarım uzasın kirlensin ellerim ayaklarıma 

ama onların vakti yoktu onlar için 

ve onlar için çocuk duvara kadar 

gidip gelecekti salıncak ceviz dalında 

ve komşunun ölüm çocukları 

güçlükle göğüslerine tutunan nefesleri 

Öldürmeye alışmaları karar kılışları 

Toprağı karıştırıp şaşkınlıkla içlerine giriyorum onların 

Ansızın bir kravat bazen bir kaç sene deniz 

renkli horozlar ve karanlık doğan yarasa 

sık sık anne tekrarı 

ve kalbinde allah yazan çocuk 

kızlar hızlanan gelinler 

erkeklerde insen uğultuları 

çocuklar ki mutlaka kutupta bırakılan 

ve dönülen bayrak

Beni buruyorlar renklerin gidip gelişleriyle 

içinde kanlı zincirler elden ele 

yıldız süzerken kadınların karınlarında doğururken 

dilleri terleri damaklarıyla ısırdıkları pamuklar 

ağızdan ağıza 

ve meydanlara 

cılk çıkan yığılan çocuklar

bağıran balık 

suyu zorlayan midye 

üzerimizden akan gemi karınları 

- Çocuk kanlarla sarsıldı 

öğrenciliğim korkunç öğretmenlerim

sızı olduğum kızlar 

onların şehvetime dokunup kalışları 

anı 

akıllı bir öğrencinin alayındayım 

kanımı ve kamalarını arıyorlar 

aceleyle elleriyle cepleriyle 

bedenime kanımı yapışık olarak 

ya da kumaşa emdirerek 

akıtacak olan 

ve bedenimi arayan korkumu 

açıklıyorlar önüme

(korkumu ölümümle ağzıma kilitlemişim) 

İnsanlar salıncak altlarında solur 

-Güneş hep aynı artist çocuktu 

Nilüfer ipi çok ince parmaklarıyla 

dağlara göklere en yakın elmacık kemikleriyle tutmuş 

yüzüme gülerek severek

3

Şimdi yağmur birikiyor kubbelerin içine 

ak yürek baraj büyüyor 

yarış su pirinç ve içinde canlı çevrilen insanın 

çiçekle döşenen başı

            Balıkçı tezgahları 

            Kayıkçı tezgahları 

            Ekmek tezgahları

yağmur alınlara doğruldu 

secdeye durdu süslendi ölümle sözleşen 

ateşli hastalar gibi', '1 Onlardı uzak yerler seçtiler  ve sayesiz ilahları  Kalın ovalar kuşları yaklaşan ağaçlar  ve taşlaşan boğulu kalan nağra  bir sarnıç kemer...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":117,"source_url":"https://www.antoloji.com/hesaplanmadan-olu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daralan Vakitler', 'daralan-vakitler-cahit-zarifoglu-yix4v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yanakları saçları gözleri yanmış 

Zehirli gaz bombaları 

Yılan gibi sokmuş yalamış gövdelerini 

Ağızları, küçücük dilleri yanmış 

Bütün Beyrut sapsarı kalmış 

Sanki ağlamak imkansız 

Başları 

Paletlerle ezilmiş babaları 

Yahudi doğramış analarını 

Binlerce çocuk topların betonların altında

Beyrutun gözyaşları şimdi 

Kudüsün yanıbaşında 

Müslümanlarsa uzakta 

Sanki başka 

Gelinmez bir dünyada

Acın bir vadi 

Zehirli çiçekler bir ova gibi karşımda

Gözüm baksın sadece 

Ayrıntıları 

Kıvrılıp kırılmış bilekleri 

Kemikten yakılmış etleri 

Kuma serilmiş cesetleri

Büyük ajansların yaydığı resimleri 

Bir seyirci gibi görsün dursun 

Bir kadın gibi ağlasın..

Beyrut yengeç kıskacında 

Çoğu müslüman kafir yanında 

Yaslanmış yastıklara sonunu beklerler filmin

Sen filistin hokkaları doldur kanla 

Şairler eğer ahın varken 

Uzanırlarsa tomurcuklara güllere 

Herbiri kanlı bir ateş gibi korku 

Bir azar bir şamar olsun

Filistin sen işine bak kar toprağını 

Yoğur gazabını yaradanın..

Bu ateş bulutu hangi kavmin üzerinde 

Çam ormanlarının salınışında 

Kuşların cıvıldayışında 

Otların serin tenlerinde 

Eğer varsan bakıp görmeye 

Şeffaf perdenin az ötesini 

Bir ateş bulutu var en bildik yerde 

En emin yerde

Ve bak asıl ölen yaylalar villalar tok karınlar 

Hissiz dudaklar gayretsiz kalpler 

Asla değil kavruk çölde yatan kadavralar

Farzet körsün olabilir 

Elele tut 

Taş al ve at 

Kafiri bulur

Hani ceylanların 

Hani cihat marşın

Bir yumruk harbinden nasıl kaçtın 

En arka safta bile kalmadın 

Cengi attın dünyaya daldın 

Tezeğe konan sinekler gibi

Dönüyor burgaç 

Dünya üstten yanlardan daralıyor 

Ovalardan 

Dar geçitlere sürülen sığırlar gibi 

Bir gün ister istemez 

Karşısında olacaksın kaçtıklarının

Dua et 

O gün henüz mahşer olmasın', 'Yanakları saçları gözleri yanmış  Zehirli gaz bombaları  Yılan gibi sokmuş yalamış gövdelerini  Ağızları, küçücük dilleri yanmış  Bütün Beyr...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":64,"source_url":"https://www.antoloji.com/daralan-vakitler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşu', 'kosu-cahit-zarifoglu-kmr39', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mağaralar taştan yolcu örüyor 

Böyle üstünlük görülmemiştir bir bebek 

Göğü sevmeyi 

Ve yerden korkmayı biliyor 

Kendine bir ses bekliyor bir sarık 

Aleme tanrı

Bir bebek susar nihayet 

Sezer de ağaçların otların 

Topraktan çıktığını

Bir bebek ağlar 

Bir bebek mor ağzından 

Bilinir söyleyince

Zerdüşt nereye gittiyse 

Hep kartalı gördü

Ve güneş tek hüneriyle 

Bir yaprağı kertenkeleyi çakıltaşını 

Ve mor olduğunu suların

Beyin tırtıl 

Taş taşlar taşların 

Dipsiz süresiz seslerine tırmanır 

Çünkü ses katlanır 

Kazılır kayalara 

Ses geçilir iki kaşın arasından 

Sonsuz nefes alır 

Ülkedir dudakta

Zerdüşt neredeyse 

Kartal orada yığınak 

O 

Zincirli ayakların durmadan çıktığı 

Tek bir basamak

Kaya gözlü ağaç saçlı 

Taşın içindeki böcek 

Bu ilk fırtına kapısında

Taşın içinde böcek 

Taşır kendini yürür 

Bedenini bir uçtan bir uca 

Nabzı vurur dinler şaşırır 

Çalışan eşyasını yakalar 

Sorar fare kuş balık

her şey kendi yerinde 

Taşın içindeki böcek 

Ki inanır 

Ve çatlar taş

Gök eğilir 

O geçer kartalıyla

Yüreği büyülenir burkulur 

Gözleri gerilir 

Ağzından bir donanmayla bekler 

Mermer yerine şahlanır 

Çizilir kanar

Bardağa ilk düşen damlasında 

Uyuyan güvercin 

Ve ilk taşan damlasında 

Bir azgın güvercin 

Bulutları saçlarından sürükler 

Bayram yerlerini geçer hızla

Bir sabah kartalın bembeyaz kadınıyla 

Dağlardan düzlere nehirlerle 

Çırpınarak çığlıklar atarak 

O 

Durmadan saratustra', 'Mağaralar taştan yolcu örüyor  Böyle üstünlük görülmemiştir bir bebek  Göğü sevmeyi  Ve yerden korkmayı biliyor  Kendine bir ses bekliyor bi...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":61,"source_url":"https://www.antoloji.com/kosu-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavga', 'kavga-cahit-zarifoglu-825ce', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taş ve sopa 

  İki köylü karşı karşıya 

  Kavak ağaçları şahit 

  Bir de ibibik kuşu

  İncir yalnız 

  Badem yeşil kabuklu

  Camdaki hayalinle 

  İki öfkeli boğa

  Sevdalılar kapışıyor 

  Tabiatın ortasında

  Irmak göz kırpıyor akıyor 

  Çoban köpeği şöyle bir bakıyor

  Yaman indi omzuna sopa 

  Güçlü çarptı taş başına 

  Hayalin akıyor kanda 

  Yüzün zonkluyor yarada 

  Taş ve sopa 

  İki köylü karşı karşıya', 'Taş ve sopa    İki köylü karşı karşıya    Kavak ağaçları şahit    Bir de ibibik kuşu   İncir yalnız    Badem yeşil kabuklu   Camdaki hayalin...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":18,"source_url":"https://www.antoloji.com/kavga-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatil', 'tatil-cahit-zarifoglu-d6i6s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nehirler 

  Uzun uzun ağlayan söğütler 

  Birine bir kadın tutunmuş 

  Biri bir kaval üfürüyor 

  Sürü nerdeyse görünür

  Akşamın zili olmalı 

  Bazı kulaklardan tam-tamlar 

  Karışır büyücü ağzı 

  El eli tutar gözyaşı boşanır

  Daha başındayız iklimin 

  Kızıl saçların 

  Kor bakışın

  Kulübeler yanıyor 

  Yaramz çocuklar, yaramz çocuklar 

  Balçık emiyor gövdeyi 

  Devrilmiş bir ağaç yanlarıda 

  Toplanıyorlar, doğuya bakıyorlar 

  Masallarda bir delik olmalı

  Çok geç

  O akşam geç vakit 

  Sokak serserileri yolumu bekliyor 

  Adımlarım, çözülen kıravatım 

  Yanımdan bir atlı kalkıyor 

  Hayır kan, kan sızıyor

  İlkin bir köpekbalığı ağzı 

  Kıyasıya başbaşayız 

  Beraber olduğumuz günlerden biri 

  Haykırıyor

  Derken biri daha 

  Çene açılıp kapanıyor 

  Paralayan diş bir baş kapıyor 

  Son bir söz daha 

  Bir yalvarış kırıntısı olmalı 

  Duyanı olmayan, Allahtan başka

  Sana bu soruları uzatıyorum 

  Son nefes sorusu 

  Çil yavrusu gibi dağılıyor yakınların 

  Mezar sorusu 

  Çil yavrusu gibi dağılıyor yakınların 

  O sorular sorusu

  Korkma zor değil 

  Korkma korkma zor değil 

  İyi bir alışkanlık edindiyse kalbin 

  Kork ama umut et zor değil', 'Nehirler    Uzun uzun ağlayan söğütler    Birine bir kadın tutunmuş    Biri bir kaval üfürüyor    Sürü nerdeyse görünür   Akşamın zili olmal...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":44,"source_url":"https://www.antoloji.com/tatil-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açık Açık Çağırır Aşkını', 'acik-acik-cagirir-askini-cahit-zarifoglu-lleo5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1

Çabuk akan tez giden 

ilk geyik avında ölenler 

çarpıntı başlarıdır insanlığın

Uzakta.Ta burada 

Ünlü bir can sıkıntısını 

Ufalar bir zümrüt sakal

Yeldeğirmeni 

ve uçuşan leylekler 

beyaz saçlı atın 

kar yıllığını rüzgar hallerini 

kahraman atın 

madalya anına bitişik 

dört nala koşan sesi 

oradan uzaktan  ta buradan

siyah 

çatık kaşlı gelincik tohumlarına 

benzer sezişliriyle 

gelişir yapılı kaygılar

2

bir ayıp giyotin 

çün ağaç sağa dönmez 

soldan kuşatılır 

çün ağaç şaşırır 

ağaç ölür 

Ama sapına kadar 

Bilhassa büyük 

Erkek 

Tam erkek bir el 

Yani kolun ucuna kadar gelmiş de 

Yumruk bile olmuş

ve bilhassa bu büyük bir el 

beynelmilel bir sabah seli 

katlayıp büküp yapma çelikleri 

gündelik insanı kaldırıp 

bir de tanrıya şarkısını söylerse

Belirli bir yapısı 

belli bir geçmişi olan 

nereye değdiğini bilen 

düğün yapısı fırçasıyla 

toprak ve topraktan sonrasını 

aynı çığlığı atan 

ve karalar içinde

3

haydi

şu kaçar su durur mu 

gök içimizden bir zenci çağırır 

zenci zenci 

bir büyük geniş başlı 

şikayet mi ne olur

açık açık çağırır aşkını 

burda mı daha mı uzakta 

bütün bir geceye 

dayar alnını

öyle ki alın 

mübarek bir şeydir', '1 Çabuk akan tez giden  ilk geyik avında ölenler  çarpıntı başlarıdır insanlığın Uzakta.Ta burada  Ünlü bir can sıkıntısını  Ufalar bir zümr...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":56,"source_url":"https://www.antoloji.com/acik-acik-cagirir-askini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Filmden Tek Kare', 'bir-filmden-tek-kare-cahit-zarifoglu-tb4sq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bal akıyor kayalar 

Sarp yalçın bir bal 

Yakınında ne ayı pençesi ne insan eli

Komşu bir şelale 

Komşu kuvvetler 

Bazı iradeler 

Geceyi katlayıp balyaladılar

Boynu vurulacakmış gibi 

Korkuyla büzülüyor uykusunda diktatör

Sıcak o afrika 

Saf yüreği yolunarak yaratıldı masaya 

Eldivenli beyaz bir el 

Rulet gibi döndürüyor onu 

Birbirine çevrilebilir bir dabe olarak 

Ortada 

Karanın yanında vahşi hayvanları da 

İri demir parmaklıklı yumruğun zamiri olarak 

kafes odalarda siyahın yanında 

Eldivenli ve beyaz 

Döndürüyor afrikayı 

- Buradan daha iyi görünüyor majeste 

- Tank you 

Geçiyor kraliçe 

Bırakıyor uzun eteklerini geceye

Şimdi bir eksersiz daha 

Baştan alalım yeni bir çabayla 

Bal 

Kaya 

Üzerine hala pazarlık yapılmamış 

Simsiyah kaşlar ve beyaz gözaklarında 

Kırmızı kılcal damarlar 

Vahşi hayvanlar kafesinde 

Parmaklıkları tutuyor 

Batıda bir ada devletinde 

Gemi-vinç-kara Gemi-vinç-kara', 'Bal akıyor kayalar  Sarp yalçın bir bal  Yakınında ne ayı pençesi ne insan eli Komşu bir şelale  Komşu kuvvetler  Bazı iradeler  Geceyi katl...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":35,"source_url":"https://www.antoloji.com/bir-filmden-tek-kare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başaklarda', 'basaklarda-cahit-zarifoglu-5n6no', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece yanımızda bağrımızda 

Bir tomurcuk ıslığı hayat şakrak. Söyle 

Bu geç vakit kim tırmalayan kapısını 

Gece yanımızda bağrımızda

Kolumda bir ışık gibisin 

Yürüyoruz şehre atlılar gibi

Çiçek açan şehre bakıyoruz 

Aşk ki bizim berrak gökdelenimizdir 

Sargıları açıldı bileklerim zinde 

Gözlerim tek tek geçiyor iklimleri 

Şanlar içinde

Yabancılar yağıyor sabahları 

Netlikle bulduğum sen misin 

İçimde akar 

O yeraltı suları  sen misin

Bu araçlar biraz 

Yana kaymalı

Gerçek esvaplar sahi delikanlılar 

Mimikler dalışlar birden kavrayışlar 

Dokunulmaz ısılarıyla gövden deniz ve martılar

Bir için 

Akıyor iki yanında söğütdallarının kavisleriyle 

Sevinçlerin 

Bir silindir geçiyor üstümüzden 

Esneklikle yumşa dayan ağırlıklara

Bakalit unufak oldu 

Öfke kırıldı 

Serçe öldü

Yalvarıyorum biraz daha 

O zift ve zülüf çağında

Gerildi ev 

Yorgunluklar ve neş''e

Duvarlar mukavves 

Çatı bir eğri kaburga kemiği daha yükleniyor 

İşte iki mavi bilye

Elimde aşkın ülkesine yol kağıdım 

Bin asırlık başım 

Kuzgun saçlarım

Benim için 

Aynı yalvarışlarla uzanıyor musun hala 

Senin He''n benim Hey''im', 'Gece yanımızda bağrımızda  Bir tomurcuk ıslığı hayat şakrak. Söyle  Bu geç vakit kim tırmalayan kapısını  Gece yanımızda bağrımızda Kolumda ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":41,"source_url":"https://www.antoloji.com/basaklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kımıl', 'kimil-cahit-zarifoglu-wpwgl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çiçektozu üstümüz başımız 

Bak sen geldin

Deniz kıyısına kurmuşlar mescit 

Yunuslara sırtlarını dayamışlar

Defneler dallarını açıyorlar 

Serin gölgelerde çınlıyor nefesimiz

İmam saflara bakıyor ışık vererek şehla 

Alınlarda secde mühürleri kıble hoşluğu

Kuşum güvercin,kuşum uyan bekle 

Uzun etekler hatır soracak süpürerek kır otlarını

Bir yaprak daha çevirdiler 

Bir halka daha genişledi avluda çınar ve minare

Seven kollar açılıyor sarılıyor açılıyor 

Peşpeşe tavşan yavruları su samurları

Oturup bir nefes daha derinlediler

Tesbihlerin yolunu birbirine ilediler', 'Çiçektozu üstümüz başımız  Bak sen geldin Deniz kıyısına kurmuşlar mescit  Yunuslara sırtlarını dayamışlar Defneler dallarını açıyorlar  Ser...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":16,"source_url":"https://www.antoloji.com/kimil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağcılıklarım', 'dagciliklarim-cahit-zarifoglu-phil9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Parçlanmaktan arınmış evcil olan 

Yabana koşar bir aman 

Kaçıp kuytulardan 

Derisini sıvazlıyan yangınla yalaz 

Ve döşüne varan bileklerini 

Kent 

        dev dev bir kedi sokulmalığı 

        belirdikçe daha ağır fakat hareketli

Yarmaktan arındın evcil 

(yani 

sofrada 

elimle birlikte ekmeğe uzanır eli)  kurtağzı 

gibi istekli 

herbir yaprağında soluk soluğa 

o ulu insan 

insan 

yaban çiçeklerini

Sonbahar günleri sağlık ve istekle 

sikkeler çaktım uçurumlu gövdene 

Güvendim 

Demiri alıp ısıran boşluklarına

Yüz metre kayayı 

Yedi vuruşta indim 

Hep birlikte omuzum 

demir halka ay 

                gibi 

                şekillenen bildiklerim 

O buzul yarda kar yataklarında 

Dağla armızda 

Yalnız ve yalnız 

Dostluk vardı aramızda

Adem: 

      buzulun bıçakcısında öldürülmeden kelimeleri 

      peki ama nerede gururum 

      ne oldu ona demişti 

Ak hafif saygı duyarak 

Soyunarak dağ keçisi sargılarından

- ille dert mi ola alemde 

- dağsözün dinledik iflah olduk

Cilo kar yalabı 

Süphan halat aklı başında sağlam 

Değişik gergin 

Burulurken iklimin kar kırmaları 

Her yükseklikte 

Dağla yanyana durur bedenim

Cilo Cilo karağlarken 

Buz kaymağı yanağın

Dağ ve hava blokuyla 

ben 

dağ hava ve ben üçümüzün 

gözü yekdiğerinin zirvesinde 

dağ insan zirvesine tırmanıyordu bende 

hava yatay bir uçurumla karşılaşır hemen 

en küçük bir korku kabarmışsa ciğerlerimde

Bu küçük urganın 

Küçük derli toplu ve ejder ağızlarıyla 

O uzak kişilik çığrışlarıyla 

Altta ormanlara 

Aşıp ummana kavuşan ulamalarında 

        (büyük kent - insan  - ilişkiler - kitaplık vesaire gibi)

Bir öz konuşma başlar 

Şiir ve mahalliler üzerine

eksi bir eksi onbir 

eksi bir eksi yirmibir

1

Şimdi uzak su kaplan kası aşındırır ışıltıyı 

Bir ipek ince halı 

Serilir metabolizması üzerine ve dürülüp içine 

Aşktan rençberliğe azamet eyleyen dervişlerin

Haydin kalkalım 

Adaşım ve kanilişkim olan beyaz çiçekler 

Kömüre başkaldıran kara açmamak için 

Ve kadın vuruşundan başka 

Yaklaşım bilmeyen böcekler

Şimdi uzak şu kadar 

Durmadan olaha habire

2

1974 yazında 

        dünyada 

        toprağın hırçın çalkantılarından yadiğar 

sarp üzerine sarp bir tepesinin önündeyiz 

tüm hazırlıklarımızla

o kış başparmağım donmuştu 

yeni yeni çözüldü donu

Şimdi ulanıp dolanıyoruz urganlara 

Yükselirkenlerde 

Solucanların toprak yemesi gibi durmadan 

Etimden geçiyor dağın derisi

Biraz daha

Karlar başlıyor 

Ve ecdadım nasıl oralara tırmanmışsa 

Kanımda bir gürcü beygiri 

Tesbih gibi aklımı çekerek 

Götürüyor oralara 

    ve sonra açlığın verdiği korkularla 

    bir kaygı basıp giriyor içime 

Esenliğimi - dedim ki 

                  ben gidiyorum 

                  ardımdan postala

Bir tek an''dır dağcılık 

Sineğin camda 

kımıldamadan 

durduğu bir kaç saniyeyi hatırla

Ve ne uzun oldu duyargalarım 

Şimdi kayanının yapısındaki tuz 

            granit 

            fosfat 

            alüminyum 

            demir ve çarpıntı yataklarından 

Aşk ihtilacındaki bir delikanlı gibi geçiyorum

Sanki 

Duyargalarımın 

duyargalarının 

duyargayarı ile 

duyuyor gibi

O yozgatlı çocuk 

    ayak bileğini tuttu - Kırılmıştı

O gibi 

daha inceleri 

dağı fobilerden uzak 

teknik-sağlam halat- 

uçurumlardan bakabilme yeteneği 

düğümcülük sananlar 

dağcı bir kere hata yapar tasasıyla yatıp kalkarlar 

Düşerek 

Çarparak koldan ayaktan 

ve belden kırıldılar

Ya o niksarlı 

    üzgündü 

buzul görmeye dayanamıyorum 

    demiş 

    ağlamıştı

Ya gaziantepli fazlı 

krater gölündeki kar suyuna atmıştı kendini', 'Parçlanmaktan arınmış evcil olan  Yabana koşar bir aman  Kaçıp kuytulardan  Derisini sıvazlıyan yangınla yalaz  Ve döşüne varan bileklerini ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":134,"source_url":"https://www.antoloji.com/dagciliklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilık Kocaman Bakışlar', 'ilik-kocaman-bakislar-cahit-zarifoglu-zhr31', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Verimsiz bezgin 

Geçti günler 

Uçtu çekip karnından kopardığım tüyler 

Şen miyim martıları koluma takarak 

Bir güç denemesiyle pazularım 

Kahverengi-kendi kendine canlı-kabararak 

Birara bütün kuvvetlerim elimde 

Öyle ki dalgalar gibiyim 

Bir okyanus kalbinde 

Çevirdim hem üç kere numaranı 

Birileri bir cumartesi 

Müthiş morarıp genişlediğini bildirdiler 

Şaka mı bu hayır şırrak bir şok 

Üzülmüyorum korkmuyorum ağlamıyorum 

Sadece 

"Melenkoliniz uğradı" diyor pansiyoncu kadın 

"Haber vereyim dedim yoktunuz dünden beri 

bekliyor odanızda" 

Elimle 

Kendi elimi tutuyorum 

Yan yana gidiyormuşum gibi kendimle 

Ah yine bir aldatmaca durma koş 

Bu ses 

Telefonun olabilir 

Yineliyorum kendimi 

Önüne itiyorum hayalinin ölü seslerin 

146 31 çift sıfırdan 18 çalıyor 

Kaldırıyorum ahizeyi 

Mazara şu 

Beton kalıplarının içine akıyorsun harçla 

Gelebilir miyim mümkün mü 

Vıdı vıdı çenebaz sokaklar 

Düşman baltalar vitrinler yola doğru küstah 

Gelir miyim dersin 

Yaban çehrelerin tırpanlarını göze alarak 

Koca kent bir sancı dayanamayıp kalabalığa 

İlk eczaneye dalacağım 

Hani şöyle birden sessizlik yumuşak 

Minik hafif eller cam tezgahta 

Sürüngen 

Em 

Aspirin 

- Bana bir aspirin 

- Kutu tablet? 

- Farketmez 

  Isırmasın da timsah gibi 

Ilık kocaman bakışlar 

Şaşırmak isteyerek 

Biri saklasın beni 

Eskilerin yüzaklarından 

Bir incelik gösterin 

İncinmesin yüreğim 

Hala içerdeyim dikkatle bakıyor eczacı kadın 

- Otuz liranız yok muydu 

Olabilirdi sancıyla susuyor bakışım 

Biri bağırarak konuşuyur 

Biri giriyor 

Veya öyle bir sükut 

Başka? 

Hava sıcak nemli ağır 

Ağustos temmuz 

Kuru havaları arıyorum 

Bir de isteğim var 

Dişlerim onaltı yaşımdaki gibi olabilir mi bir gecede 

Bakışlar boşuna 

Kırmızı dudak izleri mektuplar boyunca 

Bir yalan 

Ansızın uyanıyorum her gece 

Biliyorum bahçede dolanıyorlar 

Solukları kapı önünde 

Beni istiyorlar 

Onlarla yemek yiyorum düşümde 

Kendimi yalnız bildiğim her gece 

Yalvarışım ağlayışım 

Cenkleşiyorum kendimle 

Medet 

İmdat 

Bir ses kaydına 

Upuzun iniltiler bekliyorum 

Danışman olarak gırdapları 

Yeryüzünden arta kalan bütün deprem kırıntılarını', 'Verimsiz bezgin  Geçti günler  Uçtu çekip karnından kopardığım tüyler  Şen miyim martıları koluma takarak  Bir güç denemesiyle pazularım  Ka...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":81,"source_url":"https://www.antoloji.com/ilik-kocaman-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hama: Sımsıcak', 'hama-simsicak-cahit-zarifoglu-5e83s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hac yolunda bir merhale 

Kalbin ve cesedin azık yeri

Tekkeler zaviyeler medreseler ve ulema 

Yemiş yüklü ağaçların kolları kökleri

Saf ve seven bir göz gibi bakan şehir 

Şimdi tüller arkasına geçmiş gibi

Büllbül yolar dudağını 

Bakınca kara aklın batağına

Yetmişbin şehit 

Sayısınca billur kase

Öyle bir sarsan ses 

Gür gümrah dalmış Hak''la yarenliğe

İçinden akan nehir 

İki yakayı çatan nehir

Ak durmadan ak 

Yetmişbin kola ayrıl beş kıt''a ak

Sarıklar kan oldu 

Ak sakal kan oldu

Demek bitmedi kerbela 

Hama kerbelası dehrin

Nasıl kuru dudakları devlet olduysa Hüseynin 

Şehit ağzını değdir üstüne ölü kalbimin

Bülbüller anıp susar sesini 

Nice tevhit çekti dillerin

..ve üstüm başım perişan benim 

Elim hayret kısa kamalarım kayıp

De şehit nefesini değdir üstüne ciğerimin', 'Hac yolunda bir merhale  Kalbin ve cesedin azık yeri Tekkeler zaviyeler medreseler ve ulema  Yemiş yüklü ağaçların kolları kökleri Saf ve se...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":27,"source_url":"https://www.antoloji.com/hama-simsicak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-cahit-zarifoglu-7b335', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha dün sesler 

Hatta insan sesleri 

Karın altındaki 

Toprağın içindeki köklerde 

Toprağın altındaki bitki kökleri 

Ne sabırlı bir rüya 

Çektikleri 

Beklerken kesilirken çürürken 

Toprağın dokunulabilir teninde bahar 

Yani şöyle (Dönüş yapıyorum)

Biz görenedek 

Çiçekler dağlara yamaçlara 

Vuranadek 

Bahar, derisi altında yaşamanın 

Bir inek yayılıyor orda 

Bitkilerin karanlığında 

Bir sümbül 

Yeri hazır 

Gelecekte uzak bir iklimden kelimesi 

Demir bakır 

Tuz granit 

Bütün madenler 

Suyun büyük çeneli ağzında 

- Çalkala 

Bahar 

O sabah 

Hamile bir kurt gibi yürüyor dağlarda 

Azığım koynumda 

Uçuşan rüzgarda 

Bir ipekli fular gibi boynumda 

Bahar 

Bahar 

Celladımızsın sen benim 

Yaydığın etlere bak 

Yeraltında akıyor esintin 

Sesini işitiyorum 

Yüreğimden bir adın daha geçiyor 

Derken 

Serpilip ırmak olacak bir su kalkıyor 

Kımıltısız kuru topraktan 

Düşünüyorum', 'Daha dün sesler  Hatta insan sesleri  Karın altındaki  Toprağın içindeki köklerde  Toprağın altındaki bitki kökleri  Ne sabırlı bir rüya  Çe...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zarifoğlu']::text[], 9, '{"poet":"Cahit Zarifoğlu","poet_slug":"cahit-zarifoglu","theme":"Türk Klasikleri","is_hero":true,"total_lines":41,"source_url":"https://www.antoloji.com/bahar-540-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Sofrasında Yedi Kişilik Bir Aile Oyunu', 'aksam-sofrasinda-yedi-kisilik-bir-aile-oyunu-cahit-zarifoglu-7b7vs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I

Önce kim - "önce sen"

Dirilen bir işci olmalıyım. Öyle olmalıyım ta eskiden 

(Ağlayarak)  anlamlıydım olmalıyım anlıyarak 

İşci türemedi hiç bir şey türemedi 

bezirgan ölü tükendi köle ölü bitti 

bir yazı sağdan sola kıvrılarak eğilip 

bükülerek bir şekil almalıydı 

önce kim - "önce o" 

dirilen bir işçi olmalıydı

İşçilik kime kaldı görüyorsunuz 

çocuklarım 

"çocuklarım nerdesiniz" baba sofrayı hoplatarak 

Baba tanrıya yalvar 

malar

"işçi miyim değil miyim" 

durmadan kendini yorarak kurcalayarak 

soruyor (bu kim bizden değil)

Kendini darağacına atsa 

ağırlığı az gelir boğulmaya - ve atmadı

Beni mi adasalar iyi olan beni 

diledikleri yerine gelsin diye kurban 

çünkü hep budanmışım gibi 

koyun bazen horoz gibi algılıyorum bazen omuz etlerimi 

"intiharla (oysa mı)  bir çelişmeydik eskiden 

yasaktık intiharla 

canımızın hakkı üzerine 

varamazdı elimiz

"intihar bulun intihar kurbanlara" 

onların değişen sesi bu ağabeylerimin 

sofrada apaçık duyuyorum işte 

kendilerinden kaçıp koşuyorlar bu sofra boyunca 

"nasıl olur ama tohumları babamın" 

"nasıl olur ama başka bir ırk" 

"Başka bir ırk mı" sürüyor onlardan

Bu ev sofrası kuruldukça 

Camlar kaykılıyor ve bahçede ağaç 

Tehlike kuşları kaldırıyor 

Düşsel bir oyun olan çocuklar 

Lar - onlar laronlar 

hala sağdan sola yazılan babam 

bozulmaz akıllar kullanıyor 

yaşlanıyor ama bozulmuyor ve diyor 

"çünkü bozulmazdan yapıldık

Bu ev sofrası kuruldu önce baba 

Oraya pencereden ağaca ve kuşlara 

"çünkü ağaç işarettir içimizin sorularına 

kuş işarettir doğup ruhları 

dev gibi sallanan çocuklara" 

Bu ev sofrası kuruldukça ana 

Oradan pencereden ağaca ve kuşlara 

"çünkü ağaç problemdir çok karışık bundan böyle aklım 

kuşlarsa uçar gider uzaklara"

O başka yargılar öteki başka bakar 

Ellerindeki meşalelerle topraktaki kovuklara 

Yaklaşan laronlar lar - onlar çocuklara 

bakıp 

bakıp sofraya. Ana 

yemeğe yaklaşıp ekmekle koklaşarak 

/ "bereketli küpler 

yağ küpleri ne demek bilmez bunlar 

geberesi dinsizler 

gel ekmek keseyim seni" /

"Koklaşmak mı ekmekle savaşmak"

Anaya onların gönül kıran sesleri ağabeylerimin 

İ''yle başlayan ve birbirinin aynı isimleri 

Yani i ile i ve i''yle i 

              i olur mu i "diyor" 

İki değişik ad olmalı onların ki 

"iki değişik ağbeyim benim 

               yok mu ki" 

Sofrada önce arkaya sallanarak 

kız ekmekle alışveriş etmeden 

