INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1919-1933''ten Bir Parça', '1919-1933-ten-bir-parca-faruk-nafiz-camlibel-yggyk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O günlerde bir ünlü ayak bastı Samsun''a,

Yürüdü etrafında ümitler suna suna.

Bu, ateşler içinde geçip gelmiş bir erdi,

Göğsünde toplanmıştı milyonla Türk''ün derdi,

Bu milyonla dert ona veriyordu başka hız,

Yürüdü arkasında genç, ihtiyar, kadın, kız.

O kimdir? Bakışları deniz kadar yumuşak,

Saçı güneşi emmiş bir demet altın başak.

O kimdir? Bir milletin sesi vardı ağzında,

Ondört milyonun nabzı çarpıyordu nabzında.

O kimdir? Geçtiği yer dönüyor gün vurmuşa,

Can veriyor sararmış ot
..........
..........', 'O günlerde bir ünlü ayak bastı Samsun''a, Yürüdü etrafında ümitler suna suna. Bu, ateşler içinde geçip gelmiş bir erdi, Göğsünde toplanmıştı ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlıbel']::text[], 9, '{"poet":"Faruk Nafiz Çamlıbel","poet_slug":"faruk-nafiz-camlibel","theme":"Türk Klasikleri","is_hero":true,"total_lines":14,"source_url":"https://www.antoloji.com/1919-1933-ten-bir-parca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garipler', 'garipler-faruk-nafiz-camlibel-tp91x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her duyduğum gülüşün yok sevinçten haberi.

